-- GENERATED by `wfj generate` from data/quest/quest-0097.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [97000] = { "Venatura della memoria", "Cerca nei campi dell'⟦Alliance=Alleanza⟧ distrutti di Hyjal tracce del padre di Abigail Sawyer, Lawrence.", "Prima di questa... seconda vita, ho imparato la venatura del legno nella bottega di mio padre.\n\nQuando la guerra raggiunse Hyjal, lui rimase indietro, a fabbricare armi per chi era diretto alla vetta. Io fuggii a Lordaeron. La sua ultima lettera arrivò da quell'accampamento sulla montagna, e poi non ebbi più notizie.\n\nLa mia morte fu probabilmente non più dolce della sua. Al mio risveglio a ⟦Undercity=Sepulcra⟧, sembrava fossero passati anni, ma ne erano passati appena due.\n\nSembri in grado di affrontare la salita. Qualsiasi resto tu trovi di mio padre, Lawrence Sawyer, mi darebbe sollievo.", nil, nil, 0x1f5695c6, 0x2c24c8e7, 0x2c6481dc, nil, nil, "...mm" },
  [97001] = { "L'eredità dei Sawyer", "Porta il Registro della Famiglia Sawyer ad Abigail Sawyer nel ⟦War Quarter=Quartiere della Guerra⟧ di Sepulcra.", "Dentro l'armadio, un registro annota scambi di fieno, legname, animali da tiro e terre. Altre note, personali e incompiute, sono infilate tra le sue pagine.\n\nLe cifre raccontano la loro storia: la famiglia Sawyer era abile nel trasformare il legname in armi, attrezzi, mobili e carri.\n\nSfogliando le pagine si scoprono altri parenti della famiglia. Abigail Sawyer figura tra i parenti.\n\nLe interesserebbe molto.", nil, nil, 0x4051d83c, 0x5d0d13e9, 0xdd4e1535, nil, nil, "...mm" },
  [97003] = { "Chol'aruk il Divoratore", "Porta la testa di Chol'aruk a Gur'ak, nelle ⟦Barrens=Savane⟧.", "Ehi, tu, {class}. Mi serve il tuo aiuto. Si dice che una bestia abbia la sua tana nel fondo di una caverna ai ⟦Thorn Hill=Colli Spinosi⟧, a nord-est di qui. I ⟦Razormane=Chiomaguzza⟧ la chiamano Chol'aruk, o «il Divoratore». Pare che sia cinque volte più grossa di un normale verrospino, con una sete di sangue che non si placa mai.\n\nI più non credono a queste storie. Io sì, perché ho già combattuto contro bestie simili.\n\nTrova la sua tana e uccidi Chol'aruk. Portami la sua testa. Ma ti avverto: preparati bene e non andarci da <solo/sola>.\n\nSangue e tuono, {class}.", "Ci è voluta la forza di sei combattenti esperti per abbattere una di queste creature, e nonostante ciò è riuscita a stenderne quattro prima che potessimo finirla.\n\nSe queste bestie mostruose comparissero in numero maggiore, i danni che i verrospini potrebbero infliggere a questa terra sarebbero catastrofici.", "Notevole, {class}. Nessuno dubiterà più dei miei racconti quando tornerò a Orgrimmar con questa macabra prova dell'esistenza di questi abomini. Ma sappi che questa gloria è tua, e parlerò a gran voce delle tue imprese.\n\nLok-tar!", 0xc67797d5, 0xf7cb3419, 0x73b1b3d7, 0x6c001dd2, 0x8617a389, "....." },
  [97005] = { "Chol'aruk il Divoratore", "Porta la ⟦Chol'aruk's Head=Testa di Chol'aruk⟧ a Bainham, nelle ⟦Barrens=Savane⟧.", "Si dice che un abominio colossale abbia la sua tana in una caverna a nord-ovest di qui, sull'altopiano chiamato ⟦Thorn Hill=Colli Spinosi⟧. I ⟦Razormane=Chiomaguzza⟧ lo chiamano Chol'aruk, o «il Divoratore», e chi l'ha visto dice che è così enorme da poter inghiottire un orco intero.\n\nPochi credono a queste storie, ma io sì... perché ne ho affrontato uno simile con le mie mani. Sull'onore di coloro che ho perso per colpa di queste creature, questa bestia deve morire.\n\nRaduna alleati forti e trova la tana di Chol'aruk. Uccidi l'abominio e portami la sua testa.", nil, nil, 0xc67797d5, 0x5efacf98, 0xef594ded, nil, nil, "...mm" },
  [97006] = { "Rivendicazione notarile", "Porta il Registro della Famiglia Sawyer al ⟦Royal Overseer Bauhaus=Sovrintendente Reale Bauhaus⟧ nel ⟦Trade Quarter=Quartiere del Commercio⟧ di Sepulcra.", "Ho aggiunto una nota e la mia firma accanto al mio nome sulla pagina originale.\n\nPortalo al ⟦Royal Overseer Bauhaus=Sovrintendente Reale Bauhaus⟧ al Censimento di ⟦Undercity=Sepulcra⟧ e spiega dove è stato trovato. Deve sapere come è arrivato a me mentre io restavo alla mia bottega.\n\nPuoi dirgli con franchezza che Abigail Sawyer ha raccontato la sua storia lacrimevole a un altro sconosciuto e che tu avevi davvero i mezzi per darle seguito.\n\nDi nuovo, grazie per aver fatto questo per la mia famiglia.", nil, nil, 0x34053bae, 0x2ca290c2, 0xa9f3b860, nil, nil, "...mm" },
  [97007] = { "Resti di legno", "Riporta il Registro della Famiglia Sawyer autenticato ad Abigail Sawyer nel ⟦War Quarter=Quartiere della Guerra⟧.", "Ho timbrato le pagine pertinenti per i registri di Abigail e aggiornato i nostri documenti.\n\nAbigail dovrà inviare un seguito al Censimento Reale quando intenderà trasportare una qualsiasi delle proprietà in territori dei Reietti.\n\nPuoi restituirle il suo registro e portarle con esso un promemoria: i suoi obblighi contrattuali con il commissariato del Quartiere della Guerra non sono ancora stati adempiuti, perciò farebbe bene ad aspettare prima di tentare di far valere uno qualsiasi di questi diritti di proprietà precedenti alla guerra.", nil, nil, 0x73fe4ab0, 0xb7768aa0, 0x26410a41, nil, nil, "...mm" },
  [97009] = { "Il tormento di Maerion", "Porta $N1 Aculeo di Vilsegugio a Maerion Thaelemaches a Dae'gun.", "Lasciato a sanguinare e abbandonato, gettato da parte perché un esercito potesse fuggire. Dovevo morire comprando loro qualche istante.\n\nInvece sono stato maledetto a sopportare, costretto a guardare demoni sempre ardenti finire ciò che l'acciaio non è riuscito a fare. Questo è il mio destino.\n\nMa qualcosa sta cambiando. L'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ tornano su questa montagna profanata, e la guerra si risveglia.\n\nLa mia furia le risponde.\n\nSe anche la tua lo fa, dimostralo. Portami due manciate di aculei di vilsegugio da questi Segugi Profanatori.\n\nIl dolore allineerà le nostre volontà.", nil, nil, 0xca90f5f4, 0xb7886262, 0x9f7d6d50, nil, nil, "...mm" },
  [97010] = { "Vendetta cieca", "Sali in cima alla Torre dei Maghi dell'⟦Horde=Orda⟧ e lancia un Frammento Runico Esplosivo per segnalare a Maerion Thaelemaches di sferrare l'attacco contro i demoni.", "I frammenti incisi di rune sono pronti. Lasciati cadere da abbastanza in alto, si frantumeranno all'impatto, squarciando armature e carne di demone.\n\nC'è una torre che domina questa landa desolata. Ci darà l'altezza di cui abbiamo bisogno.\n\nSaliamo. Resterò nell'ombra e proteggerò il tuo fianco.\n\nQuando arriveremo in cima, fammi segno effettuando il primo lancio. Farò piovere la rovina su di loro.", nil, nil, 0x9f315c13, 0x4c3b6399, 0x24a6be48, nil, nil, "...mm" },
  [97017] = { "Il tuo primo ⟦Riding Ram=Montone Cavalcabile⟧", "Ispeziona i Montoni Cavalcabili per scegliere la tua prima cavalcatura.", "Ah, è un gran giorno per te, vedo; sei qui per il tuo primo montone, eh?\n\nQuesti montoni sono i più saldi e robusti di tutta Azeroth. Sono ferocemente protettivi verso il loro cavaliere. Sì, farai fatica a trovare un compagno più fedele per i tuoi viaggi.\n\nQuindi hai una scelta importante da fare. Tu e il tuo montone viaggerete insieme per il mondo, quindi scegli con saggezza! Non preoccuparti, qualunque scelta farai sarà quella giusta.\n\nVai a vedere i montoni e torna da me quando hai deciso.", nil, "Ah, quello è un ottimo compagno e ti servirà bene, {name}.\n\nSono orgoglioso di essere io a mandare te e il tuo ariete per la vostra strada. Mi pare che l'ariete che hai scelto sembri già affezionato a te. Spero che ti prenderai buona cura di lui, e lui di te.\n\nNon dimenticare di passare a trovarmi ogni tanto! Mi piacerebbe sentire le vostre avventure insieme.", 0x7f649662, 0xc7e22043, 0x98dc8147, nil, 0x0f5bffd6, "...m." },
  [97018] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da ⟦Ultham Ironhorn=Ultham Ferrocorno⟧.", "Salve, {class}! Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un montone, a pagamento, ovviamente.\n\nVeron ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i montoni.", nil, "Ehilà, {class}! Sono felice di vedere che hai completato il tuo addestramento con il vecchio Ultham. Meno male che ti ha mandato da me!", 0x70893089, 0xd951fb2b, 0x44eb15dc, nil, 0x5a7b9e45, "...m." },
  [97022] = { "Rapporto a Danitha", "Parla con Danitha Morr al Forte Bandarion.", "Danitha Morr ti ha ordinato di tornare al Forte Bandarion per ricevere ulteriore addestramento. Torna al forte il più in fretta possibile.", nil, nil, 0x8da1b01c, 0xe99f5883, 0x37976c93, nil, nil, "...mm" },
  [97029] = { nil, "Consegna la Lama Celeste Antica a Ealaane Calcanembi per saperne di più.", nil, nil, nil, 0x81e4c1c3, 0x782a5d21, nil, nil, nil, "e.mmm" },
  [97045] = { "Il tuo primo cavallo", "Esamina i cavalli da sella per scegliere la tua prima cavalcatura.", "Salve! Sei qui per esaminare i nostri cavalli?\n\nQuesti destrieri discendono sia dalla storica razza di Lordaeron sia dai nostri cavalli locali. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Non dimenticare che tu e il tuo cavallo viaggerete insieme per il mondo. Sono certo che qualunque scelta farai sarà la più adatta a te.\n\nVai a esaminare i cavalli e torna da me quando avrai deciso.", nil, nil, 0x001ed422, 0x4dfd35cf, 0x158ac1f1, nil, nil, "...mm" },
  [97046] = { "Il tuo primo meccatrampolo", "Esamina i meccatrampoli da sella per scegliere la tua prima cavalcatura.", "Salutazioni! Vedo che oggi è davvero un gran giorno: oggi sincronizzerai i tuoi dati biometrici con il protocollo di rilevamento del cavaliere del tuo primo meccatrampoliere! Questo protocollo aiuterà il trampoliere a distinguerti da altri possibili cavalieri.\n\nPerciò hai una scelta importante da fare. Tu e il tuo trampoliere viaggerete insieme per il mondo, quindi scegli con saggezza! Non temere, qualunque scelta farai sarà quella giusta.\n\nVai a esaminare i meccatrampolieri e torna da me quando avrai deciso.", nil, nil, 0xc18e78f9, 0x580b869f, 0xdd6129cd, nil, nil, "...mm" },
  [97047] = { "Il cuoco in gabbia", "Trova una chiave per la gabbia di Wendel e un travestimento con cui farlo sgattaiolare fuori, nell'Insediamento di Kurzen.", "Ehi! Tu! Devi aiutarmi! Stavo solo esplorando la giungla quando, all'improvviso, questi pazzi mi hanno teso un'imboscata! Non so cosa vogliano farmi, ma li ho sentiti parlare di tigri e di riduttori di teste, e non voglio averci niente a che fare!\n\nNon so come, ma devi tirarmi fuori di qui! Ti prego! Una chiave di questa gabbia, un travestimento per sgattaiolare via, qualcosa! Qualsiasi cosa!", "<Il giovane nella gabbia è in preda al panico. Riesce a malapena a mettere insieme le parole.>", "<Un'ondata di sollievo attraversa il volto di Wendel.>\n\nOh, grazie! Grazie mille, <amico/amica>! Mi hai davvero salvato la pelle.", 0x2f0f87ce, 0xcbd4ea81, 0x88f0903a, 0x7d4889ad, 0x7179f9b7, "....." },
  [97048] = { "Ritorno in porto", "Parla con la capitana Aransas alla ⟦Booty Bay=Baia del Bottino⟧.", "Senti, adesso non posso ripagarti, ma sono il cuoco della nave della capitana Aransas. Metterò di sicuro una buona parola per te quando tornerò alla ⟦Booty Bay=Baia del Bottino⟧. Dovresti parlare con la capitana appena puoi. Sono certo che sarà felice di riavermi a bordo.", nil, "Ah, tu devi essere {name}. Mathers mi dice che siete evasi insieme dal complesso di Kurzen. Dice che voi due avete fatto rotolare bene qualche testa. Che bei bucanieri, voi due!\n\n<Il capitano Aransas si ferma per valutare la tua reazione.>\n\nHa ha! So che è tutta una balla, amico. Mathers è un bravo ragazzo, ma l'unica lama che sa maneggiare è un coltello da cucina.\n\nIn ogni caso, ti sono grato per aver salvato un membro della mia ciurma. Un buon cuoco non ha prezzo in questo mestiere.", 0xd608f137, 0x2d90b9f5, 0xaaf806d7, nil, 0x600f07ad, "...m." },
  [97049] = { "Essenza di melme stillanti", "Raccogli $N1 Essenza di Melma Stillante nella Terrazza del Plasmatore.", "Se stai andando alla Terrazza del Plasmatore, vorrei chiederti un favore.\n\nCi sono segnalazioni di melme che vivono nelle pozze vicino al Cristallo Acromatico incolore. Credo che la loro essenza possa essere utile per i miei esperimenti e vorrei che mi portassi dei campioni da studiare.\n\nNe varrà la pena per te.", nil, nil, 0x865a3952, 0x756fc3f6, 0x4d0f6b81, nil, nil, "...mm" },
  [97065] = { "Far pendere la bilancia: ⟦Keefer's Angelfish=Pesce Angelo di Keefer⟧", nil, nil, nil, nil, 0x9099a156, nil, nil, nil, nil, ".mmmm" },
  [97066] = { "Far pendere la bilancia: ⟦Brownell's Blue Striped Racer=Pesce Striato Blu di Brownell⟧", nil, nil, nil, nil, 0x8c2e8a32, nil, nil, nil, nil, ".mmmm" },
  [97067] = { "Far pendere la bilancia: ⟦Dezian Queenfish=Scienide di Dezian⟧", nil, nil, nil, nil, 0x96bb5eae, nil, nil, nil, nil, ".mmmm" },
  [97074] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Jartsam.", "Salve, {class}! Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un felino, a pagamento, ovviamente.\n\nLelanai ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i felini.", nil, nil, 0x70893089, 0x343bf588, 0xf22585e5, nil, nil, "...mm" },
  [97119] = { "Ora si cucina", "Porta $N1 Panino Saporito di Cervo a Ortak Lomgok nella Selva Antica.", "Oltre a occuparmi dei bisogni spirituali della gente di qui, li sfamo anche. Non sono propriamente un cuoco addestrato, ma dopo cinque anni ho imparato un paio di cose sulla preparazione del cibo!\n\nSono certo che la gente qui adorerebbe assaggiare qualcosa di diverso. Ricordo che, prima di radunarci sulla montagna, c'era un goblin di ⟦Everlook=Lungavista⟧ che serviva vassoi di minuscoli Panini Saporiti di Cervo... Mi piacerebbe assaggiarne ancora uno. Anche qui abbiamo un sacco di cervi! Pensi di poterne cucinare un po'?", nil, nil, 0x16762640, 0xcdb1da52, 0x169d1dee, nil, nil, "...mm" },
  [97130] = { "Antichi segreti dei Gurubashi", "Recupera un Idolo Antico dei Gurubashi dalla Città Sommersa.", "Lan'dalock e io abbiamo discusso di una recente novità nei mari del sud riguardante un'antica rovina dei Gurubashi apparsa all'improvviso al largo della costa della Valle di Rovotorto.\n\nUn sito simile ha un notevole valore archeologico. Saremmo molto interessati a ottenere uno degli idoli che certi santoni tra gli antichi Gurubashi usavano come focus rituale per la loro magia del sangue.\n\nEntra in questa \"Città Sommersa\" e recupera uno di questi idoli per noi.", "La magia di sangue dei Gurubashi è molto sgradevole, ma comunque estremamente affascinante. Lo sapevi che gli antichi imperi dei troll avviavano periodicamente un rituale noto come «Luna di Sangue» che induceva deliberatamente una follia e una sete di sangue insaziabili nell'intera popolazione?\n\nPerché infliggere deliberatamente un periodo di caos e carneficina spietati al proprio popolo? A quale scopo? È profondamente affascinante in senso accademico, ma rabbrividisco al pensiero di quanto dovesse essere brutale la vita in una cultura simile.", "Grazie per averlo recuperato. Lan'dalock e io dibattiamo da tempo sulla natura della magia di sangue dei Gurubashi. Un manufatto come questo dovrebbe essere inestimabile per aiutarci a comprendere meglio questa magia primordiale.", 0xefbd092f, 0x4a847e99, 0xab7e1556, 0x8a1f7c2b, 0x93f2badc, "....." },
  [97168] = { "Aiuto materiale", "Se vuoi aiutare Eldrun Solcatempeste a ⟦Ironforge=Forgiardente⟧, portagli un ⟦Azerothian Diamond=Diamante Azerotiano⟧ e un ⟦Pristine Black Diamond=Diamante Nero Intatto⟧.", "{name}, gli spiriti pesano, sia materialmente sia spiritualmente. Ho bisogno del tuo aiuto. Nel profondo della Scholomance a Lordaeron si trova il Grande Ossario, fitto di ombre. Sto costruendo un dispositivo per squarciare quel buio, ma mi mancano i mezzi per finirlo.\n\nPortami due diamanti: uno Azerotiano e uno Nero Intatto. Non sono oggetti banali, già: semplicemente non ho io le risorse. Potresti procurarmi i due diamanti?", nil, nil, 0x2664d220, 0xc092eff6, 0x59299744, nil, nil, "...mm" },
  [97169] = { "La minaccia di Razziabuio", "Usa il ⟦Divination Scryer=Veggente della Divinazione⟧ nel cuore del seminterrato del Grande Ossario, nella Scholomance. Così facendo evocherai degli spiriti che dovrai combattere. Sconfiggerli richiamerà il ⟦Death Knight Darkreaver=Cavaliere della Morte Razziabuio⟧: sconfiggilo.\n\nPorta la ⟦Darkreaver's Head=Testa del Razziabuio⟧ a Eldrun Solcatempeste nella Caverna degli Inganni, a ⟦Ironforge=Forgiardente⟧.", "Il ⟦Death Knight Darkreaver=Cavaliere della Morte Razziabuio⟧ domina il Grande Ossario nella Scholomance. Minaccia di piegare il regno degli spiriti al suo volere e va fermato! È qui che entra in gioco il Veggente che hai aiutato a costruire.\n\nUsa il Veggente della Divinazione nel cuore del seminterrato del Grande Ossario per richiamare i servitori spirituali di Razziabuio. Sconfiggi gli spiriti e il cavaliere della morte in persona apparirà. {name}, portami la sua testa! Solo la sua morte invertirà il danno fatto al regno degli spiriti!", nil, nil, 0xf4f3bcea, 0xba92656d, 0x4c7d637c, nil, nil, "...mm" },
  [97170] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Randal Hunter.", "Salve, {class}! Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un cavallo, a pagamento, ovviamente.\n\nKatie ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i cavalli.", nil, nil, 0x70893089, 0x1b612170, 0x5d6758f4, nil, nil, "...mm" },
  [97171] = { "Il tuo primo cavallo", "Esamina i cavalli da sella per scegliere la tua prima cavalcatura.", "Salve! Sei qui per esaminare i nostri cavalli?\n\nQuesti destrieri discendono sia dalla storica razza di Lordaeron sia dai nostri cavalli locali. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Non dimenticare che tu e il tuo cavallo viaggerete insieme per il mondo. Sono certo che qualunque scelta farai sarà la più adatta a te.\n\nVai a esaminare i cavalli e torna da me quando avrai deciso.", nil, nil, 0x001ed422, 0x4dfd35cf, 0x158ac1f1, nil, nil, "...mm" },
  [97173] = { "Magia degli Zannanera", "Recupera un Totem Rituale degli Zannanera dalla ⟦Blackmaw Hold=Tana degli Zannanera⟧.", "I mezzorsi Zannanera sulle montagne che sovrastano Azshara si sono dedicati alla magia oscura. Anche se un popolo primitivo corrotto dalla magia demoniaca non è una novità per Azeroth, Lan'dalock e io vorremmo studiare i loro focus incantatori.\n\nRecati alla roccaforte nota come ⟦Blackmaw Hold=Tana degli Zannanera⟧ e recupera per noi uno dei Totem Rituali degli Zannanera. Solo gli sciamani più potenti degli Zannanera ne portano uno, quindi porta alleati e fai attenzione.", nil, nil, 0xd8ada7f4, 0xdca24cad, 0xd8ed8c41, nil, nil, "...mm" },
  [97174] = { "Un'impresa degna", "Parla con Danitha Morr al Forte Bandarion, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "È giunto il momento, {name}. Come in vita, i paladini dei Reietti non sono completi finché non riescono a legarsi a un destriero da battaglia. Non è una cavalcatura qualsiasi: è un potente spirito della punizione.\n\nParla con Danitha Morr al Forte Bandarion per saperne di più. Ti guiderà su cosa fare dopo. La strada davanti a te sarà difficile, ma come amano dire i nostri alleati orchi: sangue e tuono, <fratello/sorella>!", nil, nil, 0x402fd91d, 0x1a2c29f4, 0x1c23bcfe, nil, nil, "...mm", nil, nil, 0xc694a950, nil, nil },
  [97175] = { "Un sacrificio dovuto", "Recati a Orgrimmar e procurati l'⟦Exorcism Censer=Incensiere per Esorcismo⟧ dal sommo sacerdote Zayus. Dovrai fare una donazione di 150 monete d'oro per ottenerlo.", "Nessuna impresa degna si compie senza qualche sacrificio e questo primo compito richiede proprio questo.\n\nDevi procurarti l'incensiere per esorcismi del sommo sacerdote Zayus per il tuo compito. Anche se il suo uso sarà per una buona ragione, deve essere data una giusta compensazione.\n\nRecati a Orgrimmar e parla con il sommo sacerdote Zayus. Zayus chiederà una... \"donazione\" per la perdita del suo incensiere. Sarà un piccolo prezzo da pagare a conti fatti.", nil, nil, 0x3e84aca3, 0xe68879ed, 0x02e6b947, nil, nil, "...mm" },
  [97176] = { "Esorcizzare ⟦Terrordale=Valterrore⟧", "Usa l'⟦Exorcism Censer=Incensiere per Esorcismo⟧ per scacciare gli spiriti tormentati di ⟦Terrordale=Valterrore⟧. Dopo aver distrutto 25 Spirito di ⟦Terrordale=Valterrore⟧, torna da Danitha Morr al Forte Bandarion, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Ho aggiunto all'incensiere un po' di terra dal suolo contaminato di ⟦Terrordale=Valterrore⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Vai lì e usa questo incensiere per trovare le aree con i segni più forti di corruzione. Le riconoscerai dalle aure necrotiche verdi che si levano dal suolo nel punto in cui si radunano anime tormentate.\n\nUsa l'incensiere per rivelare questi spiriti. Liberali dal loro tormento. Quando avrai dato pace a queste anime, torna e discuteremo i prossimi passi.", nil, nil, 0xb8674f67, 0x99847261, 0x5c3f0c74, nil, nil, "...mm" },
  [97177] = { "Atti di misericordia", "Riporta l'⟦Exorcism Censer=Incensiere per Esorcismo⟧ a Danitha Morr al Forte Bandarion, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Con la benedizione dei loa, prendi l'incensiere. Ce l'ho usato più di una volta per esorcizzare i brutti spiriti voodoo, e dovrebbe servirti bene per le prove che verranno.\n\nFarai meglio a tornare da Danitha ora, {name}. La tua missione continua con lei.", nil, nil, 0xfee28d3f, 0x323486ba, 0xea1025c3, nil, nil, "...mm" },
  [97178] = { "⟦Ott=Nov⟧ del ⟦Tarren Mill=Mulino di Tarren⟧", "Parla con ⟦Ott=Nov⟧ nel villaggio del ⟦Tarren Mill=Mulino di Tarren⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "Il destriero di un paladino ha bisogno di una bardatura adeguata, altrimenti è poco più di una bestia senza cervello. La bardatura usata dal tuo destriero non solo deve essere dei materiali più pregiati possibili, ma deve anche essere adatta a sintonizzarsi con il regno degli spiriti.\n\nC'è un fabbro fuori dal ⟦Tarren Mill=Mulino di Tarren⟧ che ha fatto un ottimo lavoro per i nostri paladini in passato. È un orco modesto e schivo, ma il suo lavoro è eccellente e adatto alle nostre esigenze. Cercalo e commissionagli questo incarico.", nil, nil, 0xb7610888, 0xabd4c144, 0x4ac46d23, nil, nil, "...mm" },
  [97179] = { "Una raccolta di materiali", "Porta 40 Tessuto di Telarunica, 6 Lingotto d'Arcanite, 10 ⟦Arthas' Tears=Lacrima di Arthas⟧, 5 fiale di ⟦Stratholme Holy Water=Acqua Santa di Stratholme⟧ e 150 monete d'oro a ⟦Ott=Nov⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "Per la bardatura ci servono diverse cose: Tessuto di Telarunica per la fodera, lingotti d'Arcanite per la piastratura, la ⟦Arthas' Tears=Lacrima di Arthas⟧ per la sintonia spirituale e Acqua Santa di Stratholme per l'infusione spirituale. Infine, chiederei un modesto compenso per il lavoro e per la sella e le staffe da abbinare alla bardatura.\n\nPortami questi materiali e potrò completare la tua bardatura. Mi metterò al lavoro sulla sella mentre tu raccogli questi oggetti.", nil, nil, 0x85fed7c1, 0x8f97760a, 0x14e6f591, nil, nil, "...mm" },
  [97180] = { "Il miglior lavoro di Nov", "Porta la ⟦Arcanite Barding=Bardatura d'Arcanite⟧ a Danitha Morr al Forte Bandarion per un'ispezione.", "<⟦Ott=Nov⟧ si asciuga il sudore dalla fronte e grugnisce con approvazione al suo lavoro.>\n\nEcco fatto. Il mio mestiere è soprattutto la creazione di armi, ma credo che questo possa comunque essere uno dei miei lavori migliori. Ti ringrazio per la fiducia che tu e i tuoi compagni paladini mi avete dimostrato.\n\nSenza dubbio anche Danitha Morr vorrà vedere il lavoro di persona. Portale la tua bardatura e ringraziala da parte mia per avermi permesso di completare questa commissione a tuo nome.\n\nLok-tar, {class}.", nil, nil, 0xb51868fb, 0xf8c175c9, 0x97dfc029, nil, nil, "...mm" },
  [97182] = { "Un'offerta di vendetta", "Procurati un mangime speciale per cavalli, da dare a un cavallo spirito. ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, potrebbe essere in grado di fornirtelo.\n\nRecati al ⟦Dire Maul=Maglio Infausto⟧, a Feralas, e uccidi ⟦Tendris Warpwood=Tendris Legnotorto⟧. Così libererai lo ⟦Ancient Equine Spirit=Spirito Equino Antico⟧. Dagli il mangime speciale per calmarlo.\n\nInfine, consegnagli la ⟦Arcanite Barding=Bardatura d'Arcanite⟧ e spera che sia disposto a concederti la benedizione necessaria.", "La bardatura del destriero di un paladino richiede la benedizione di un potente spirito equino. Tra le rovine di ⟦Dire Maul=Maglio Infausto⟧, l'ent corrotto noto come ⟦Tendris Warpwood=Tendris Legnotorto⟧ tiene imprigionato uno spirito simile. Cerca la punizione a nome di questo spirito e liberalo dalla sua prigionia. Con un po' di fortuna, potrebbe essere disposto a concedere la sua benedizione.\n\nPer garantire il successo, ti consiglio anche di portare un tipo speciale di mangime sintonizzato spiritualmente. Viaggia nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ e parla di questo con il ranger noto come ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧.", nil, nil, 0xde30e4a4, 0xb6a2ffd6, 0x8ea53502, nil, nil, "...mm" },
  [97183] = { "⟦Blessed Arcanite Barding=Bardatura d'Arcanite Benedetta⟧", "Torna con la ⟦Blessed Arcanite Barding=Bardatura d'Arcanite Benedetta⟧ da Danitha Morr al Forte Bandarion, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Mentre la bardatura poggia sulla schiena dello ⟦Ancient Equine Spirit=Spirito Equino Antico⟧, brilla di un bianco incandescente. L'aria si carica di potere per un breve istante, poi la bardatura scompare dalla schiena del cavallo ed è ora al sicuro nel tuo zaino.\n\nAnche attraverso il cuoio della tua sacca, senti il calore che ancora emana dalla sella. Sembra che la tua offerta di vendetta sia stata accettata e che la bardatura sia stata benedetta. È ora di tornare da Danitha Morr al Forte Bandarion.", nil, nil, 0xcd7cadda, 0xb8276b39, 0x99801d9d, nil, nil, "...mm" },
  [97184] = { "Il ⟦Divination Scryer=Veggente della Divinazione⟧", "Porta un ⟦Azerothian Diamond=Diamante Azerotiano⟧ e un ⟦Pristine Black Diamond=Diamante Nero Intatto⟧ a Danitha Morr al Forte Bandarion, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Ora dobbiamo assemblare un ⟦Divination Scryer=Veggente della Divinazione⟧ che sarà vitale per la tua prova finale. L'incensiere per esorcismi che hai usato a ⟦Terrordale=Valterrore⟧ ne è il catalizzatore, e dovrei riuscire a ricavare un alloggiamento adatto per il dispositivo di scrutamento.\n\nGli ultimi componenti necessari, però, sono due diamanti: uno bianco, uno nero. Questo rappresenta la dualità della nostra natura di paladini dei Reietti. Questi due saranno il faro con cui il Veggente trafiggerà il velo tra i vivi e i morti.", nil, nil, 0x97882862, 0xe64571b3, 0xfa1703d5, nil, nil, "...mm" },
  [97185] = { "Giustizia e punizione", "Usa il ⟦Divination Scryer=Veggente della Divinazione⟧ nel cuore del seminterrato del Grande Ossario, nella Scholomance. Così facendo evocherai gli spiriti che dovrai giudicare. Sconfiggerli richiamerà il ⟦Death Knight Darkreaver=Cavaliere della Morte Razziabuio⟧. Sconfiggilo e riconquista l'anima perduta del destriero caduto.\n\nDai lo Spirito della Punizione e la Bardatura Incantata Benedetta al ⟦Darkreaver's Fallen Charger=Destriero Caduto del Razziabuio⟧.", "In questa sacca troverai gli oggetti che ti serviranno per la tua prova. Usa il Veggente della Divinazione nel cuore del seminterrato del Grande Ossario per far emergere spiriti maledetti che affrontino la giustizia. Il potere dei tuoi giudizi sarà estremamente prezioso in questa battaglia, quindi usalo con saggezza.\n\nUna volta dispersi questi spiriti, apparirà Razziabuio. Sconfiggilo e reclama l'anima perduta del destriero. Mostrale il cammino di giustizia e punizione che percorri e, con un po' di fortuna, prenderà il suo posto al tuo fianco.", nil, nil, 0xd7a36f70, 0xf593f040, 0x5575ccb6, nil, nil, "...mm" },
  [97186] = { "⟦Manna-Enriched Horse Feed=Biada Ricostituente Arricchita⟧", "Procura 20 Biscotto Ricostituente Arricchito a ⟦Nathanos Blightcaller=Nathanos Selvamorta⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. L'⟦Argent Dawn=Alba d'Argento⟧ è nota come unica fornitrice dei biscotti. Dovrai anche dare a Selvamorta 50 monete d'oro per il suo tempo.", "Quindi ti serve del mangime da dare allo spirito incorporeo di un cavallo? Interessante.\n\nSì, suppongo di poterti aiutare con ciò che ti serve. Ho passato molto tempo ad allevare bestie che sono... diciamo, non più del tutto di questo mondo, e so una cosa o due su come sostenerle.\n\nMi servono solo alcuni dei biscotti arricchiti spiritualmente che vende l'⟦Argent Dawn=Alba d'Argento⟧... e una piccola offerta in oro. Per il mio tempo, naturalmente.", nil, nil, 0x1f21fe01, 0x3feebf8f, 0x74c26f68, nil, nil, "...mm" },
  [97188] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da ⟦Binjy Featherwhistle=Binjy Fischiapiuma⟧.", "Salve, {class}! Ormai hai abbastanza esperienza di avventure perché io ti insegni a pilotare un meccatrampoliere, a pagamento, ovviamente.\n\nMilli ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza oro e ti insegnerò a cavalcare i meccatrampolieri!", nil, nil, 0x70893089, 0xad9acccd, 0x61e48e2a, nil, nil, "...mm" },
  [97194] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Kildar.", "Mok'ra, {class}. Ormai hai abbastanza esperienza di avventure perché io ti insegni a cavalcare uno dei nostri lupi, a pagamento, ovviamente.\n\nOgunaro ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza oro e ti insegnerò a cavalcare i lupi.", nil, nil, 0x70893089, 0xef07a3aa, 0xc830bf6d, nil, nil, "...mm" },
  [97196] = { "L'Occhio dell'Araldo del Freddo", "Recupera l'Occhio dell'Araldo del Freddo dai ⟦Razorfen Downs=Sotterranei di Lamaspina⟧.", "C'è un servitore del Re dei Lich che ha la sua dimora nel profondo della tana dei verrospini Testamorta nota come ⟦Razorfen Downs=Sotterranei di Lamaspina⟧. Sappiamo che usa una sfera di scrutamento per osservare e dirigere i movimenti dei suoi servitori altrove.\n\nCon questo artefatto potremmo dare la caccia agli agenti segreti del Flagello e mettere fine a loro e alla minaccia che rappresentano per Kalimdor per sempre.\n\nEntra nei ⟦Razorfen Downs=Sotterranei di Lamaspina⟧, nella tana di ⟦Amnennar the Coldbringer=Amnennar l'Araldo del Freddo⟧, e recupera per me la sfera nota come l'Occhio dell'Araldo del Freddo.", nil, nil, 0x807d643a, 0xc02af882, 0xbaa21f1d, nil, nil, "...mm" },
  [97197] = { "Frammento delle Terre del Fuoco", "Recupera un Frammento delle Terre del Fuoco dai ⟦Blackrock Depths=Sotterranei di Roccianera⟧ per Alaana Stormwalker a Mulgore.", "Muln mi dice che c'è un luogo nelle profondità più remote di un posto chiamato ⟦Blackrock Mountain=Massiccio Roccianera⟧ dove la barriera tra Azeroth e il piano elementale è stata danneggiata, permettendo a una miriade di creature elementali dal regno delle Terre del Fuoco di fuggire in questa realtà, compresi giganti grandi quanto un pilone d'ancoraggio!\n\nMi piacerebbe molto studiare qualsiasi frammento di materiale che si possa raccogliere da una di queste creature. Te la sentiresti di affrontare i ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e recuperare un campione per me?", nil, nil, 0x5792e331, 0xe1878c9e, 0x4f267383, nil, nil, "...mm" },
  [97198] = { "Magia degli Zannanera", "Recupera un Totem Rituale degli Zannanera dalla ⟦Blackmaw Hold=Tana degli Zannanera⟧.", "I mezzorsi Zannanera sulle montagne che dominano Azshara sono stati corrotti da una magia oscura e sinistra. Non conosciamo la piena portata della corruzione e quale impatto possa avere sugli elementi della zona, ma speriamo di comprenderla meglio.\n\nRecati alla roccaforte nota come ⟦Blackmaw Hold=Tana degli Zannanera⟧ e recupera per noi uno dei Totem Rituali degli Zannanera. Solo gli sciamani più potenti degli Zannanera ne portano uno, quindi porta alleati e preparati a una battaglia difficile.", nil, nil, 0xd8ada7f4, 0xdca24cad, 0x5956898f, nil, nil, "...mm" },
  [97200] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Xar'ti.", "Ehi, benvenuto {class}! Ora hai abbastanza esperienza di avventure perché io ti insegni a cavalcare uno dei nostri raptor, a pagamento, ovviamente.\n\nZjolnir ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParlami quando hai abbastanza oro e ti insegno a cavalcare i raptor.", nil, nil, 0x70893089, 0xa1231880, 0xfa7333cd, nil, nil, "...mm" },
  [97203] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Velma Warnam.", "Salute, {class}. Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un destriero scheletrico, a pagamento.\n\nZachariah ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che desideri. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò i cavalli scheletrici.", nil, nil, 0x70893089, 0xc805e1bc, 0x56b28782, nil, nil, "...mm" },
  [97204] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da ⟦Kar Stormsinger=Kar Soffia Tempesta⟧.", "Salute, {class}. Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un kodo, a pagamento, ovviamente.\n\nHarb ti fornirà una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò a cavalcare il nobile kodo.", nil, nil, 0x70893089, 0xc691cd57, 0x244c8bec, nil, nil, "...mm" },
  [97205] = { "Imparare a cavalcare", "Impara l'abilità ⟦Apprentice Riding=Apprendista in Equitazione⟧ da Genn Chiarosole.", "Salve, {class}! Pare che tu abbia ormai abbastanza esperienza di avventure perché io ti insegni a cavalcare un corridore del vento, a pagamento, ovviamente.\n\nTi fornirò una cavalcatura gratuita una volta che ti sarai addestrat<o/a> con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò a cavalcare i corridori del vento.", "Una volta imparato a cavalcare un calcaventi, potrai intraprendere viaggi con la tua cavalcatura in tutto il mondo.\n\nÈ certamente più veloce che correre ovunque. Anche se non ti fermerò, se è quello che preferisci.", "Meraviglioso! Hai fatto un lavoro fantastico. Imparare a cavalcare uno di questi calcaventi richiede spesso pazienza e mano ferma.\n\nNon scappano per natura, ma chissà quali cose tu e la tua cavalcatura affronterete là fuori nel mondo più vasto? Sì, è meglio essere preparati!", 0x70893089, 0x21d2f84c, 0x42a137db, 0x59613702, 0x53198cb8, "....." },
  [97220] = { "Il favore di Philmor", "Porta la ⟦Gatehouse Shipment=Spedizione del Corpo di Guardia⟧ all'ingresso del magazzino nel negozio Trias' Cheese, nel ⟦Trade District=Quartiere del Commercio⟧.", "Per tutta la settimana siamo rimasti a corto di scaricatori.\n\nTi va di alleggerire un po' la tabella di marcia dei nostri carichi?\n\nPorta questo pacco all'ingresso del magazzino del Gatehouse. Lo trovi dentro il negozio Trias' Cheese, al piano di sopra. La padrona, Elaine, conosce bene le consegne. Al Gatehouse arrivano spesso spedizioni in modo più discreto, per permettere sorprese cerimoniali da parte degli ufficiali della guardia.", "Vuoi riempire una cassa con le nostre migliori forme stagionate?", "Oh, cielo. Pensi che vogliamo portarla su per le scale noi? Mantenere intatti gli oggetti di valore è una tua responsabilità fino al momento della consegna.", 0xcadc7a51, 0x77beb6bd, 0x756a7024, 0x0f6c2b4b, 0xfbcc083f, "....." },
  [97222] = { "Merci per il Gatehouse", "Porta la ⟦Gatehouse Shipment=Spedizione del Corpo di Guardia⟧ su per le scale del negozio di Trias e lascialo fuori dalla porta.", "Sì, è solo una rampa di scale, ma se è una richiesta così da poco, non avrai problemi a finire la consegna da te!\n\nTrias' Cheese non fa parte del Gatehouse né del suo inventario, ma i nostri edifici condividono un piano.\n\nLascia la cassa fuori dalla porta del loro magazzino: la guardia manderà qualcuno per il solito ritiro. Vedranno il pacco arrivato e lo porteranno dentro tornando al loro posto.", "Dovresti almeno assaggiare un po' di questo cheddar stagionato. Non si riesce a smettere di mangiarlo.", "Già. C'è un motivo se quel cardine apre verso l'interno, dalla loro parte: così la porta non viene bloccata da gente che lascia roba dove le pare.\n\nConsideraci in rapporti professionali, {class}.\n\nRispettiamo i tuoi affari e ci aspettiamo che tu rispetti i nostri.", 0x2ad17834, 0xd062b437, 0x4288f8d0, 0xc9e39695, 0xb35fbfba, "....." },
  [97223] = { "La matriarca dei Bloodtalon", "Porta gli Eggs of the Bloodtalon Matriarch a ⟦Xar'Ti=Xar'ti⟧, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Tutti i raptor che vedi davanti a te li ho addestrati io. Vengono da ogni angolo di Kalimdor, ma alcuni dei migliori vengono dai raptor Bloodtalon delle isole al largo della nostra costa.\n\nTra loro c'è una raptor, la matriarca dei Bloodtalon, particolarmente feroce: ha ucciso molti del nostro villaggio ed è diventata troppo pericolosa per lasciarla ai nostri confini. Se riesci ad abbatterla, torna con le sue uova, così potremo crescere i piccoli come alleati invece che come nemici.", "I Bloodtalon sono noti per la loro astuzia e la loro rapidità, e diventano ottimi compagni se allevati dall'uovo fino all'età adulta.\n\nPurtroppo i raptor adulti sono molto difficili da addestrare, e ho provato a catturare la matriarca più di una volta. Ma ultimamente era diventata troppo pericolosa.\n\nSpero comunque di preservarne l'eredità allevando i suoi piccoli come compagni qui a Sen'jin.", "Grazie, {name}. Sono felice che potremo preservare la sua stirpe e crescere i piccoli come nostri alleati. Hai reso un grande servizio alla nostra tribù.", 0x04cfeed5, 0xc4b71826, 0xb9b4e0b5, 0xa423bd09, 0x25bba0d6, "....." },
  [97225] = { "Idoli loa dimenticati", "Raccogli $N1 Forgotten Loa Idol sulle ⟦Echo Isles=Isole dell'Eco⟧. Portali al maestro Gadrin, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Quando fuggimmo dalle isole dove ora vivono Zalazane e i suoi simili, lasciammo indietro molti idoli preziosi che ci aiutano a entrare in comunione con gli spiriti che veneriamo: i nostri loa. Sono di grande importanza per la nostra tribù.\n\nI seguaci di Zalazane non mostrano alcuna riverenza per i nostri loa e hanno sparpagliato questi idoli per la più grande delle isole.\n\nÈ un affronto che non passerà inosservato se non riusciremo a raccogliere questi idoli, e offendere un loa è una faccenda grave.\n\nVa', trova quanti più idoli loa puoi e riportameli.", "Hai trovato i nostri idoli loa, {name}? Dobbiamo riprendere presto i nostri rituali.", "Oggi hai compiuto una grande impresa per la nostra tribù.\n\nA differenza di altre tribù, il nostro legame con i loa è fatto di riverenza e rispetto, e dobbiamo loro molto.\n\nNon vorrei che i ⟦Darkspear=Lanciascura⟧ perdessero il loro favore.", 0x3a6e02f8, 0xd654e4c4, 0x689f1998, 0x682f9535, 0x0b095262, "....." },
  [97234] = { "Sala di lettura", "Porta il materiale di lettura impacchettato alla Biblioteca di ⟦Stormwind=Roccavento⟧.", "Sei qui per discutere i significati più profondi delle nostre celebri leggende? No?\n\nBe', quando avrai finito di dare un'occhiata, puoi portare questo alla biblioteca per me? Stiamo scambiando alcune delle nostre opere meno popolari con scritti più moderni. Ho una lista di tomi che il bibliotecario, ne sono certo, potrà procurarci nell'ambito del nostro accordo attuale.\n\nSe ci aiuti, i rinfreschi del club li offriamo noi.", "Per favore, abbassa la voce.", "Vediamo un po'. Il Circolo del Libro di Roy, vero? Riconosco questa tecnica di impacchettamento.\n\nBeh, se lui dice che è di questo che la gente vuole parlare, per me va bene. Il materiale che ci ritorna è sempre in buone condizioni come quando l'abbiamo prestato, quindi sappiamo che lo trattano con rispetto, per quanto le parole possano essere provocatorie.", 0x3eee958f, 0xfdbaaa05, 0x221f294c, 0xaee85b9a, 0x453e623d, "....." },
  [97236] = { "⟦Fang of Githyiss=Zanna di Githyiss⟧", "Consegna la ⟦Fang of Githyiss=Zanna di Githyiss⟧ a qualcuno ad Aldrassil che si interessi allo studio dei ragni.", "Un esemplare fresco di una bestia di queste dimensioni è una bella scoperta. Forse qualcuno ad Aldrassil che si intende dello studio dei ragni sarebbe interessato alla zanna.", nil, "Bene, bene. Quanto adoro le sorprese, {name}.\n\nQuesto esemplare mi aiuterà di certo a proseguire i miei studi.", 0xc0cb6394, 0xe6a4e5ad, 0x9adc9237, nil, 0xd5fbb580, "...m." },
  [97237] = { "Presi dagli scaffali", "Trova tutti i testi da leggere sparsi per la biblioteca, poi torna da Roy Lewells nel parco di Roccavento.", "Ho controllato il nostro inventario e tutti i titoli elencati dal signor Lewells sono al momento disponibili.\n\nDovrai però prenderli dagli scaffali da te. Parte del nostro dovere di bibliotecari è la vigilanza, e per questo tornerò alla supervisione dei registri.\n\nRiportare il materiale a Roy per conto suo non ti renderà responsabile della sua restituzione: come indica la sua nota, fai da corriere ufficiale del club del libro. Sarà il loro circolo a farsi carico di quell'onere.\n\nBuona giornata, {name}.", "Hai dimenticato cosa dovevi fare nell'istante in cui hai varcato la porta, eh? Capita a tutti.", "Sono loro! Alcuni hanno persino un profumo esotico! Fantastico, non vedo l'ora di avere conversazioni vivaci su questi scritti.\n\nNella cantina dopo l'orario di chiusura, ovviamente.\n\nGrazie per la rapida commissione, {name}. Come promesso, offre la casa. Qui manteniamo la parola data.", 0xa2b3432f, 0xa187b795, 0x7efc8438, 0x6507ccfd, 0xac97da81, "....." },
  [97242] = { "Il miscuglio di Yelmak", "Prendi alcune talee dai Cattail e dagli Speargrass che crescono lungo i corsi d'acqua nella ⟦Valley of Honor=Valle dell'Onore⟧ e torna da Kor'geld, da Yelmak's Alchemy and Potions.", "Yelmak non vuole che il suo apprendista rompa qualcosa. Be', qualcosa più di quanto abbia già rotto.\n\nMi ha detto che il giovane miscelatore in addestramento ha troppo orgoglio per chiedere aiuto quando ne ha davvero bisogno. Yelmak vuole fargli assaggiare una certa ricetta fatta in casa.\n\nRaccogli un misto di talee di tifa e di erba lancia dalle piante che crescono attorno all'acqua nella ⟦Valley of Honor=Valle dell'Onore⟧. Ci andrei io, ma se lasciassi la bottega, Whuut capirebbe di sicuro che stiamo assecondando il suo umore.", "Scopriamo formulazioni e ricette mostrando vecchi ingredienti alle nuove generazioni, che li sperimentano a modo loro.", "Questo tipo di tifa e di erba-lancia è unico di Orgrimmar. Bevendo dall'acqua sorgiva delle montagne di Azshara e nutrite dal sudore e dalla polvere minerale intrisa di sangue della nostra terra rocciosa, queste erbe racchiudono potenti poteri.\n\nLe darò a Yelmak, che forse potrà riconquistare l'attenzione di Whuut con una lezione pratica.", 0x90c5761e, 0xc53ac54f, 0xb4681896, 0xaeb14159, 0x19d48937, "....." },
  [97243] = { "Il richiamo del fuoco", "Porta la Torch of Dormant Flame a Olariaan Swiftburn allo Shrine of Flames, nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Anche se siamo nel regno di ⟦Skywall=Celaria⟧, questo resta il piano elementale. Gli spiriti di tutti e quattro gli elementi ci parlano, se ci degniamo di ascoltare. Uno di noi Plasmatori di Venti è in particolare sintonia con l'elemento del fuoco: uno shen'dorei di nome Olariaan Swiftburn.\n\nPortagli questo allo Shrine of Flames, nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧. Lo troverai nascosto lungo il bordo dell'isola, a ovest di Valanaar.", "Sì, {name}? Che cos'hai lì?", "Dunque hai portato la torcia. Sì, giovane {class}, posso insegnarti a rispondere al richiamo del fuoco. Non sarà facile, ma niente di ciò che facciamo in questo regno è mai facile.", 0x53f3b76b, 0x10e8fa30, 0xb32aea3b, 0xacd1e0ef, 0x89691ed7, "....." },
  [97244] = { "Il richiamo del fuoco", "Uccidi Skypriest Faladiel nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧ e raccogli il ⟦Faladiel's Heart=Cuore di Faladiel⟧.", "C'è uno Skypriest degli Al'Aketh di nome Faladiel. Un tempo era un invocatore della fiamma e un fedele Plasmatore di Venti. Come tanti Al'Aketh, ha barattato la sua lealtà con il potere, e ora le sue mani sono macchiate del sangue dei suoi ex fratelli e sorelle.\n\nTroverai lo Skypriest Faladiel alla fattoria a nord-est, oltre Valanaar, appena a sud del ⟦Shrine of Akir=Sacrario di Akir⟧. Uccidi il traditore. Portami il suo cuore. È un compito macabro, ma serve per il rituale che dobbiamo compiere.", "Il cuore di un traditore è un reagente potente. Le fiamme accetteranno avidamente un'offerta simile e arderanno più intense mentre lo consumano.", "I Plasmatori di Venti non dimenticano, e il sangue si paga sempre con il sangue. Mi compiace che tu sia riuscit<o/a> a consegnare a quel traditore quest'ultimo, doloroso promemoria del nostro credo.\n\nTuttavia, questo cuore non sarà l'unica cosa ad alimentare le fiamme oggi. C'è un altro compito da svolgere.", 0x53f3b76b, 0x7c8f63a5, 0x8ff65707, 0x6c645a00, 0xd212b24c, "....." },
  [97245] = { "Il richiamo del fuoco", "Trova la dimora di Kuramaa negli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧ e sconfiggi lo spirito in combattimento. Quando avrai vinto, porta la ⟦Kuramaa's Mask=Maschera di Kuramaa⟧ a Olariaan Swiftburn nelle ⟦Gustberry Lowlands=Pianure di Ventobacca⟧.", "Gli abitanti degli ⟦Shen'dar Highlands=Altopiani di Shen'dar⟧ parlano di un antico spirito della foresta chiamato Kuramaa. Dicono che viva dentro un ceppo contorto in cima a una collina, vicino all'Anchor Pylon degli altipiani.\n\nVa' sugli altipiani e trova quel ceppo. Batti il pugno sulla corteccia e Kuramaa apparirà. Sconfiggi lo spirito in combattimento e portami la sua maschera di legno.\n\nMa sta' attent<o/a>: questa entità sarà straordinariamente resistente a gran parte della tua magia. Solo il tocco della fiamma potrà abbattere lo spirito.", "Lo spirito di Kuramaa è eterno, e si manifesterà di nuovo quando ce ne sarà bisogno. La sua maschera è una fonte di grande potere e si rivelerà preziosissima per il rituale che dobbiamo compiere.", "Ora abbiamo ciò che ci serve. Accenderemo la fiamma eterna e comunicheremo con gli spiriti del fuoco.", 0x53f3b76b, 0xf10b3312, 0x5b054c6d, 0x9a2396be, 0xe1d99925, "....." },
  [97246] = { "Un pasto invitante", "Va' al Borstan's Firepit e digli che Thatog vuole che sia tu a consegnare personalmente il pranzo di Migi.", "Mio figlio, Migi, se ne va sempre a giocare con i suoi amici tutto il giorno. Gli dico di passare a prendere il pranzo da Borstan, ma so che non lo fa quasi mai, perché torna a casa affamato. Questi ragazzi pensano che i loro giochi siano più importanti del loro stesso corpo!\n\nTi prego, fermati al Borstan's Firepit e digli che sei lì per consegnare il pranzo di Migi. Quasi certamente troverai Migi dietro Grommash Hold con il resto dei suoi amici.\n\nI miei doveri mi trattengono qui durante il giorno e non posso controllare ogni suo pasto.", nil, "Certo. I genitori di Migi e io abbiamo un accordo per dare a Migi un pranzo al sacco ogni giorno, ma posso assicurarmi che il ragazzo mangi solo se viene davvero a prenderlo.\n\nA volte salta il ritiro del pasto più volte alla settimana, e mi chiedo dove trovi l'energia per restare fuori a giocare.", 0xa80c265e, 0x658ca813, 0x194a00ed, nil, 0x6256c34b, "...m." },
  [97249] = { "Il cibo preferito", "Porta il ⟦Migi's Lunch=Pranzo di Migi⟧ a Migi, dietro Grommash Hold.", "Ora che so che i suoi genitori si preoccupano di quanto si riempia davvero la pancia, mi è venuta un'idea.\n\nMi hanno fatto promettere di non preparare lo stesso pasto tutti i giorni, così Migi prende gusto a più di una cosa. Eppure, ogni volta che l'affumicatoio è pieno e facciamo i panini con pancetta di maiale glassata, lui si presenta sempre a pranzo. Abbiamo cominciato a sbriciolare i pezzetti croccanti di glassa avanzati come guarnizione: una cosa che possiamo aggiungere ogni giorno.\n\nPortagli questo. Magari comincerà a presentarsi presto e a portare gli amici!", "Credo che questa la possiamo vincere...", "Borstan's Meats? È per uno di noi?\n\nOh!\n\nWow... che profumino! Gnam.\n\nGrazie per avermi portato il pranzo. Quando io e i miei amici facciamo la strada per Grommash Hold, capisco già solo dall'odore cosa servirà Borstan ogni giorno. Questo sa del mio preferito, quello glassato! Però è diverso. Mi piacciono le briciole dal sapore forte.\n\nSe sarà così buono tutti i giorni, credo che dovremo interrompere il gioco per pranzare insieme!", 0xd08fbe54, 0x1d99228e, 0x407189ff, 0x603e2035, 0x24d63088, "....." },
  [97250] = { "Accusati a torto, puniti a ragione", "Uccidi i soldati dell'⟦Alliance=Alleanza⟧ che sconfinano nelle ⟦Barrens=Savane⟧ al confine con ⟦Dustwallow Marsh=Acquemorte⟧, poi torna dal grunt Logmar a Camp Taurajo.", "<Viaggiatore/Viaggiatrice>, hai intenzione di dirigerti verso ⟦Dustwallow Marsh=Acquemorte⟧? Ho sentito mormorare che alcuni soldati umani si sono attestati al suo confine e stanno abbattendo i segnali lasciati dai nostri ricognitori tauren.\n\nSi dice che una taverna molto frequentata sia stata rasa al suolo dalle fiamme e, come è tipico dell'⟦Alliance=Alleanza⟧, ne hanno subito dato la colpa all'⟦Horde=Orda⟧! Non posso sapere se le loro accuse abbiano un fondo di verità, ma la loro incursione sulla NOSTRA terra non deve restare impunita.\n\nPrima uccidi, poi indaga!", "Notizie dal confine?", "Allora le voci erano vere! Me lo aspettavo: le tensioni lungo la costa orientale crescono da tempo. Sapevo che era solo questione di tempo prima che il conflitto si insinuasse nel nostro territorio.\n\nTuttavia, dubito che abbiamo avuto un ruolo nella distruzione della taverna. Troppi civili dell'⟦Horde=Orda⟧ dipendono da quella via per i commerci e i viaggi. Forse potresti indagare più a fondo, se trovi il tempo.\n\nIn ogni caso, l'impresa di oggi è una vittoria per l'⟦Horde=Orda⟧ e un severo monito per l'⟦Alliance=Alleanza⟧!", 0xe1de8387, 0x62527451, 0x121cc5dd, 0x92e55d42, 0xe0593283, "....." },
  [97253] = { "Pezzi e componenti", "Raccogli $N1 Handfuls of Complicated Parts nell'accampamento pirata superiore a sud di ⟦Ratchet=Porto Paranco⟧, poi torna da ⟦Wrenix the Wretched=Wrenix il Miserabile⟧ a ⟦Ratchet=Porto Paranco⟧.", "Ehi, hai un secondo?\n\nAllora, a quanto pare nessuno di quelli che ho mandato a sistemare il recente problema dei pirati è tornato vivo. Dopo cinque o sei tentativi ho pensato: «E se invece mandassi una macchina?» Salta fuori che le scimitarre, all'occorrenza, fanno anche da cacciavite, e prima che potessi richiamarla a casa era già a pezzi, sparsa per tutto il loro accampamento!\n\nRivoglio quei pezzi, e visto che è una missioncina di recupero veloce, scommetto che le tue probabilità di sopravvivere sono MOLTO più alte di quelle degli altri. Che ne dici?", "Non una parola di più finché le tue tasche non tintinnano di metallo!", "Uaaaah! Bel colpo, amico! Mi hai risparmiato un'altra delle insopportabili prediche di Gagsprocket sul costo del metallo. E soprattutto posso buttarmi subito a costruire il mio prossimo prototipo.\n\nEhm, non avevo previsto una ricompensa... Ti piacciono le scatole?", 0xc374d63c, 0xdd7fd206, 0xd685419d, 0xedc33a12, 0x0ab437e0, "....." },
  [97257] = { "Il richiamo del fuoco", "Aspetta che Olariaan inizi il rituale al Brazier of Offering e segui le sue istruzioni.\n\nDevi portare la Fiamma Eterna a Valanaar prima che scada il tempo.", "Ora eseguiremo il rituale.\n\nMetterò i materiali sull'altare e richiamerò gli spiriti della fiamma. Se l'offerta sarà accettata, appariranno e accenderanno la Fiamma Eterna. Allora tu terrai avanti la torcia e catturerai la fiamma.\n\nPorta la torcia accesa a Valanaar e mettila nel Brazier of Eternal Flames. Devi farlo in fretta, perché le fiamme dei Firelands si dissipano rapidamente qui a ⟦Skywall=Celaria⟧.", "Hai fatto bene ad arrivare fin qui. Fai onore ai Plasmatori di Venti, {name}.", "È fatta. La Fiamma Eterna arde di nuovo.\n\nLa tua prova è completa. Sono lieto di consegnarti il tuo ⟦Fire Totem=Totem del Fuoco⟧. Usa bene questo simbolo di potere nei tuoi viaggi, {name}.\n\nRicorda solo che il potere del piano elementale serve chi lo rispetta e consuma chi non lo fa. Questa è la nostra via.", 0x53f3b76b, 0x0208cd7e, 0x4a530335, 0x6aa6ef08, 0xaed39338, "....." },
  [97263] = { "Il tuo pacco è arrivato", "Consegna il pacco smarrito di Eldrun.", "<Accanto alla cassetta delle lettere sono stati lasciati diversi pacchi smarriti. Noti che uno di essi va consegnato dal ⟦Aerie Peak=Picco dell'Aquila⟧ a ⟦Ironforge=Forgiardente⟧, a Eldrun Stormbreaker. È contrassegnato come «urgente».>", "Cos'è quello che hai lì?", "Cosa! Vado ogni giorno alla cassetta delle lettere vicino alla banca a cercare questo pacco! Questa città deve rivedere la sua pianta. Non è facile orientarsi come al ⟦Aerie Peak=Picco dell'Aquila⟧!\n\nVediamo cos'ho qui... attrezzi per intagliare totem... un'ascia di riserva... una specie di congegno goblin? Questo non l'ho ordinato! Ah, lo rispedirò indietro.\n\nEhm, cioè... volevo dire... grazie per avermi portato tutta questa roba. Ecco un pensierino per il disturbo.", 0xb90615cc, 0x0f13a33f, 0xc3642e31, 0xdcbf39a7, 0xa4d81308, "....." },
  [97264] = { "Estrazione di Denterotto", "Elimina $N1 ⟦Elder Shardtooth=Orso Denterotto Anziano⟧ dalle zone vicine, poi torna da Sarna Cornobruno.", "Gli orsi Denterotto diventano più rabbiosi a ogni stagione. Competono tra loro e con i predatori della natura per le poche fonti di cibo che riescono a raggiungere.\n\nPiù spesso attaccano noi, con la fame che alimenta la loro aggressività nel freddo pungente.\n\nGli orsi sono numerosi e testardi. Con il loro numero ridotto, le famiglie che restano diventeranno più forti che mai.\n\nAiutali a procedere. Abbatti i più anziani.", nil, nil, 0x0119e46b, 0x3e42bb28, 0xfdb28fa2, nil, nil, "...mm" },
  [97265] = { "Odio per i Furiatorva", "Sconfiggi satiri Furiatorva di vario tipo a Sargeron, a ⟦Desolace=Desolanda⟧, poi torna da Aka'rai a ⟦Shadowprey Village=Predombra⟧.", "Hai mai fatto un patto con un satiro, mon?\n\nIo sì. Come potevo resistere? La promessa del potere, una conoscenza che supera di gran lunga quella di qualsiasi tomo comune... e il tutto insieme a un servitore zelante e carismatico. Cosa potevo chiedere di più?\n\nBah, certo che non avrebbero mai piegato il ginocchio davanti a un mortale. Ho contrattato quando non avevo niente, e mi hanno gettato via lasciandomi con ancora meno.\n\nOra voglio vendetta. Vendetta contro i Furiatorva. Fai irruzione nel loro accampamento a nord-est! Macchia la terra con il loro sangue immondo.", nil, "Avrei voluto assistere alle tue battaglie e sentire le loro grida miserabili mentre cadevano sotto la tua forza.\n\nMa uno di loro è di sicuro sfuggito al tuo massacro: quello a cui ho stretto la mano in un rituale di sangue versato. Finché si aggira per ⟦Desolace=Desolanda⟧, non posso rischiare di mettere piede fuori da ⟦Shadowprey=Predombra⟧. Mi ritroverebbe presto, e con la mia pietra dell'anima in suo possesso... nemmeno la morte sarebbe una via di fuga.\n\nPrima o poi la riavrò. Ma per ora il tuo lavoro è finito.", 0x80d3ee17, 0x24ba3490, 0x9c7d33bf, nil, 0xe44d1d97, "...m." },
  [97270] = { "Rissa al Maul", "Parla con ⟦Griniblix the Spectator=Griniblix lo Spettatore⟧ sopra il Maglio, nel ⟦Dire Maul=Maglio Infausto⟧.", "Ci dev'essere qualcosa di più nel Maglio di questo!\n\nForse lo spettatore rumoroso che sovrintende all'evento a ⟦Dire Maul=Maglio Infausto⟧ lo sa!", nil, nil, 0x1baf941e, 0x5af075c5, 0x3c04074a, nil, nil, "...mm" },
  [97271] = { "Maul o niente!", nil, nil, nil, nil, 0x4cd0dd21, nil, nil, nil, nil, ".mmmm" },
  [97275] = { "Tanta fretta, Whuut?", "Dai la ⟦Yelmak's Potion=Pozione di Yelmak⟧ a Whuut.", "Whuut è un prodigio. Questo è vero. Ma non ha ancora l'esperienza, la saggezza e le ore passate a rimestare per saper rispettare i processi alchemici.\n\nSta esaurendo tutti i reagenti più rari ed esotici che abbiamo senza fermarsi a esercitare e affinare le sue abilità di base.\n\nDagli questa pozione che ho preparato con un rapido metodo da tonico. Ripenserà a tutto ciò che sta facendo quando capirà che i rimedi locali e un tocco attento sono la prima vera maestria.", "Allora, cosa c'è dopo... ⟦Black Lotus=Fiore di Loto Nero⟧, ⟦Mountain Silversage=Ramargento Montano⟧...", "Grorru--eh?\n\nDici che Yelmak ha fatto questa pozione con erba-lancia e tifa senza altri reagenti? Non sapevo che i chimici avessero un vero bisogno di queste piante comuni che vediamo ogni giorno.\n\nForse ha ragione. Potrei perdermi molto saltando direttamente alla flora più rara e meno studiata.\n\n{name}, scegli una di queste pozioni che ho preparato prima. Ti ringrazio per aver trovato il tempo di visitare il nostro negozio.", 0xdbca40f0, 0xade06c15, 0xe2d2b0c3, 0x09c7d8d9, 0x71e92119, "....." },
  [97277] = { "Grund e Gozwin", "Trova l'accampamento di Grund e Gozwin sulle colline a nord-ovest. Recupera il ⟦Gozwin's Mechanic's Log=Registro del Meccanico di Gozwin⟧ e uccidi lo Snow Leopard Prowler.", "Oi, ero girato a preparare l'arrosto di cinghiale quando ho sentito il mio amico Gozwin urlare per salvarsi la pelle!\n\nZanne feroci e una macchia confusa, è tutto quel che ho visto quando mi sono voltato. Che zampe enormi! Un leopardo delle nevi si stava trascinando via la sua preda gnomica. Ho afferrato il fucile e ho sparato sopra la bestia. L'ha mollato ed è scappato via di corsa.\n\nPer fortuna non aveva fatto altro che lasciare al vecchio Goz qualche graffio profondo.\n\nTorna all'accampamento sulle colline a nord-ovest e recupera il diario da meccanico di Gozwin. E se vedi quel leopardo delle nevi, ammazza pure lui!", "Il povero Goz si preoccupa più del suo camminatore meccanico che di sé stesso. Dice che se qualcuno mette le mani su quel diario da meccanico, è fritto. Ah! Ecco perché gli ho detto che il lavoro doveva lasciarlo a casa!", "Già, non mi sorprende sapere che quel leopardo delle nevi si stava pappando il cinghiale che stavamo preparando per l'arrosto!\n\nGoz avrà un pensiero in meno ora che gli hai riportato il suo diario. Magari adesso potrà concentrare tutte le energie per rimettersi in piedi.\n\nGrazie, {name}. Prendi un pensierino come segno della mia gratitudine, per aver fatto la scarpinata e per aver protetto le colline.", 0x13ae186f, 0xe97684ed, 0x403ef042, 0x3dbaa3c1, 0xab467190, "....." },
  [97279] = { "Armi smarrite", "Raccogli $N1 Abandoned Training Weapon, poi torna da ⟦Kzan Thornslash=Kzan Sfregiaspine⟧ nell'Antro del Tirocinio.", "Con l'afflusso di nuove reclute come te, è stato difficile tenerci riforniti di armi. Il nostro fabbro d'armi, Kzan, è a corto di armi da addestramento e vorrei vedere che capacità possiedi, per farmi un'idea del materiale con cui devo lavorare. Per tua fortuna, ho una soluzione per entrambe le cose.\n\nMentre sei là fuori a farti le ossa sui cinghiali, recupera sei armi da addestramento abbandonate. Le nostre reclute fallite le hanno lasciate a terra. Fatto questo, riportale al nostro fabbro d'armi Kzan, dietro di me nell'Antro del Tirocinio.", "Throm'ka, {class}. Gorak mi ha detto di aspettarti. È bello vederti <tutto/tutta> <intero/intera>!\n\nSei <riuscito/riuscita> a raccogliere le armi da addestramento che ti ho chiesto?", "Grazie per aver riportato queste armi, {name}. Mi metterò al lavoro per ripararle per la prossima ondata di reclute.", 0x85cc0347, 0x8f4e8fc9, 0x4b72157d, 0xe3abc6ea, 0x21e3c142, "....." },
  [97281] = { "Una tempesta che cova", "Porta il Dull Stormy Orb a Rezlak, vicino alla ⟦Drygulch Ravine=Gola di Fossosecco⟧.", "<Davanti a te c'è uno strano globo dalla superficie opaca. Quando lo raccogli, una debole corrente elettrica sembra vibrare al suo interno. Osservandolo più da vicino, pare che una nebbia scura vi turbini dentro, e di tanto in tanto si scorge una piccola scintilla elettrica.\n\nÈ chiaro che l'arpia lo usava per qualche scopo. Forse Rezlak sarebbe interessato a questo oggetto?>", nil, "Uh, dove hai trovato un aggeggio forte come questo? Sai, mi ricorda l'altra cosa che il mio capo ⟦Gazlowe=Sparachiodi⟧ mi diceva sempre...", 0x1d3d3e08, 0xbc513c0b, 0x8130886a, nil, 0x703847de, "...m." },
  [97282] = { "Potenziale tempestoso", "Porta $N1 Charged Thunder Lizard Organ a Rezlak, vicino alla ⟦Drygulch Ravine=Gola di Fossosecco⟧.", "«Rezlack, quando un'occasione bussa alla porta, assicurati di essere pronto a coglierla». È un'altra perla che mi ha insegnato ⟦Gazlowe=Sparachiodi⟧, ed è proprio quello che intendo fare.\n\nQuesto globo non sembra danneggiato, ha solo l'aria di essere scarico, ma ho in mente di sovraccaricarlo per riportarlo alla piena potenza!\n\nC'è un mucchio di sauri del tuono in una gola a ovest di qui. Hanno organi che trattengono una forte carica elettrica, perfetti per questo.\n\nVa' a prenderne un po' e portameli!", "Forse ti sorprenderà che, con un nome come sauro del tuono, sparino fulmini invece di ruggire come il tuono.\n\nE invece lo fanno. Sparano fulmini, intendo.\n\nFidati, è una lezione che, se ti va bene, impari una volta sola.", "Ehi, grazie, amico! Mi hai dato davvero una grossa mano qui, e te ne sono grato.\n\nSperiamo di riuscire a ricaricarlo per bene con questi organi. Scommetto che farà pensare due volte quelle arpie buone a nulla prima di attaccare di nuovo la mia carovana. Spero proprio che funzioni.\n\nIn ogni caso, tu hai fatto la tua parte dell'accordo. Prendi questo per il disturbo.", 0xcc6ed58f, 0x1994e522, 0x12b14931, 0xaea78271, 0xe9dc28ef, "....." },
  [97284] = { "La vendetta di Vahlarriel", "Uccidi gli orchi delle ⟦Burning Blade=Lame Ardenti⟧ alla ⟦Thunder Axe Fortress=Fortezza Ascia del Tuono⟧, a ⟦Desolace=Desolanda⟧, poi torna da ⟦Vahlarriel Demonslayer=Vahlarriel Stroncademoni⟧ al ⟦Nijel's Point=Presidio di Nijel⟧.", "Se Malem è ancora viva, sospetto che gli orchi delle ⟦Burning Blade=Lame Ardenti⟧ si aspettino che presto qualcuno venga a cercarla. Saranno di certo pronti a combattere.\n\nPreferirei che tenessi un profilo basso e restassi alla larga da loro, ma è molto più probabile che cerchino di affrontarti, lama contro ⟦Burning Blade=Lame Ardenti⟧, a ogni occasione.\n\nQuindi, che ne dici di tenere il conto fin dall'inizio? Uccidine quanti più puoi, e ne varrà la pena per te.", nil, "Buon lavoro. Con tutti i tuoi sforzi contro quegli sciocchi della Fortezza Ascia del Tuono, di sicuro ci penseranno due volte prima di saccheggiare un'altra carovana di passaggio.\n\nCon un po' di fortuna, si rintaneranno dietro i loro cancelli abbastanza a lungo da estinguersi da soli.", 0x8067ec59, 0xf8a6125b, 0x9c85e944, nil, 0xebf88a96, "...m." },
  [97286] = { "Accesso alle ricerche", nil, nil, nil, "Le tue azioni dimostrano che rispetti la conoscenza. La biblioteca è aperta per i tuoi studi.", 0xd0907e8d, nil, nil, nil, 0x0972665c, ".mmm." },
  [97287] = { "Trattative astute", "Parla con l'immagine dell'arcimaga Modera, vicino a Dalaran.", "Hai fatto bene a infiltrarti nella città dei maghi, ma credo sia giunto il momento di essere più... negoziali.\n\nPer quanto mi costi ammetterlo, non c'è altro luogo su Azeroth con una conoscenza così vasta dell'arcano. Il mio brillante lavoro impallidisce ancora di fronte all'antica saggezza che il Kirin Tor ha accumulato negli anni. Credo sia ora che ci venga concesso l'accesso a questo ordine esclusivo, non trovi?\n\nPrendi il granello che hai ottenuto. Daranno di sicuro qualsiasi cosa per riaverlo. Qualsiasi cosa.", "Oh, sei tornat<o/a>.", "Lo daresti... volontariamente?\n\nNon conosco il tuo gioco, {race}, ma non posso negare il valore del tuo intervento in questo momento delicato per il nostro popolo. Non è in mio potere concederti accesso alla città in questo momento, ma un giorno... forse. Per ora i nostri ringraziamenti dovranno bastare.", 0xe4acb80b, 0x93700c3f, 0xb6c29c5f, 0x5298efe2, 0xbf73ea9a, "....." },
  [97288] = { "Tormento senza fine", "Consegna la ⟦Abominable Head=Testa Abominevole⟧ al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "<Mentre la creatura cade, la testa le rotola via. Sembra che sia stata riattaccata più volte e che a ogni nuovo attacco la giunzione si indebolisca.\n\nQualcuno a ⟦Undercity=Sepulcra⟧ saprà di più su questo singolare abominio.>", "Che cos'abbiamo qui?", "Oho! Credo di conoscere questa testa. Uno scherzo crudele della nostra Dama Oscura. E pure delizioso.\n\nCredo di sapere come usarla.", 0x88dcf75e, 0x5d3272d3, 0x045ff381, 0x2b2c91f6, 0x3d028316, "....." },
  [97289] = { "Tormento senza fine", "Porta la ⟦Head of the Baron=Testa del Barone⟧ al corpo di Othmar, a ⟦Undercity=Sepulcra⟧.", "Teste di abominio ne fabbrichiamo di continuo, ma questa è speciale. Un tempo apparteneva a un gran maresciallo dell'⟦Alliance=Alleanza⟧. Uno particolarmente sgradevole. Othmar, credo si chiamasse. La Dama Oscura ebbe il piacere di sbarazzarsene di persona.\n\nOh, i segreti che potrebbe raccontare, se potesse parlare. E può! Basta riattaccarla a un ospite adatto.\n\nVa', mettila accanto al corpo disponibile nella stanza accanto. Ma non attaccarla. Non ancora.", "<L'abominio resta senza vita, privo di una testa che lo controlli.>", "<Il corpo si contrae tornando in vita, in preda al panico mentre rivive i suoi ultimi istanti.>\n\nTu...", 0x88dcf75e, 0x8392a5dc, 0x21af4dd7, 0x09afdccf, 0xf5efb3f9, "....." },
  [97290] = { "Tormento senza fine", "Riferisci le tue scoperte al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "Tu... abominio...\n\nPerché dovrei... aiutarti...\n\nVattene...", nil, "Non collabora, eh? Eccellente. Adoro le sfide.", 0x88dcf75e, 0x76cbafb3, 0x0d26ec99, nil, 0xdfbc27f5, "...m." },
  [97291] = { "Tormento senza fine", "Raccogli un ⟦Toxic Skullcap=Cappello Tossico⟧ da Tawny Grisette nel ⟦Trade Quarter=Quartiere del Commercio⟧, dell'⟦Blisterweed=Erbavescica⟧ vicino all'istruttore di Erbalismo e dell'⟦Essence of Agony=Essenza d'Agonia⟧ dal venditore di veleni nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧, per il maestro speziale Faranell a ⟦Undercity=Sepulcra⟧.", "Ora che la testa è riattaccata, non resta che piegarla alla volontà della Dama Oscura. Non dovrebbe essere un problema. Dopo tutte le botte che ha preso, a quella bestia è rimasto ben poco cervello.\n\nDobbiamo solo motivarla.\n\nPortami un ⟦Toxic Skullcap=Cappello Tossico⟧ dalla signorina Grisette, nel ⟦Trade Quarter=Quartiere del Commercio⟧. Ah, e un po' di ⟦Blisterweed=Erbavescica⟧ dai nostri istruttori di Erbalismo, gli Alliestar. Prendine pure, sono in debito con me. E infine un po' di ⟦Essence of Agony=Essenza d'Agonia⟧. Andrà bene un qualsiasi venditore di veleni.\n\nAbbiamo una pozione da preparare!", "Sarà così bello riavere all'ovile la nostra pecorella smarrita, non trovi?", "Andranno benissimo. Vedremo quanta spavalderia conserverà il nostro illustre ospite dopo aver assaggiato il mio capolavoro.", 0x88dcf75e, 0x3c831878, 0x10e94e21, 0xe35d5b4a, 0x7ba6274b, "....." },
  [97292] = { "Tormento senza fine", "Inietta il ⟦Hissing Serum=Siero Sibilante⟧ nel sistema sopra il corpo di Othmar, per il maestro speziale Faranell.", "Ho preparato un delizioso siero che il nostro nuovo ospite troverà di certo molto... stimolante.\n\nPrendi. Versalo nel congegno che gocciola sopra di lui. Vediamo se riusciamo a fargli capire che servire con lealtà è nel suo interesse.\n\nE cerca di non farlo cadere. Non posso permettermi un nuovo assistente.", "Per i crimini di Othmar contro la Dama Oscura, metterlo sotto quell'esemplare gocciolante è il minimo che si meriti.\n\nE poi è divertente...", "Eccellente. Lasceremo che la sua carne sobbolla per un po'. Diamogli il tempo di abituarsi alla sua nuova casa.\n\nPer ora quel miserabile non mi serve più, ma lo terremo d'occhio. Ho molti progetti per il futuro di Othmar.", 0x88dcf75e, 0xcad79e1e, 0xfef7f8a7, 0x92d9ddce, 0x51def099, "....." },
  [97319] = { "Un cugino all'estero", "Trova il cugino scomparso da qualche parte sul ⟦Mount Hyjal=Monte Hyjal⟧.", "Un mio cugino a Kalimdor si sta facendo strada tra i siti più pericolosi del posto e, per quanto ne so, è diretto al ⟦Mount Hyjal=Monte Hyjal⟧.\n\nMi sembra una ridicola perdita di tempo.\n\nSe ti capita di trovarti in quella parte del mondo, sarebbe bello sapere che non si è fatto ammazzare. Per ora.", nil, nil, 0xad20a851, 0x71fdca5e, 0xcd946fa1, nil, nil, "...mm" },
  [97326] = { "Dai sassi ai sedili", "Riporta $N1 Smooth Boulder a Thra, dietro Grommash Hold.", "Ehi! Tu hai tempo per aiutarci! Lo so che ce l'hai, l'ho capito da come sorridevi guardando il gioco che stiamo facendo.\n\nQuesto posto dietro Grommash Hold è bello perché è abbastanza sgombro per sistemare le nostre pedine. Ma la cosa brutta è che non abbiamo abbastanza sassi per fare sedie o tavoli.\n\nTu sei grande e forte... pensi di poter portare qui qualche sasso di media grandezza, abbastanza liscio da sederci sopra se ci serve una pausa?", "È bello non dover sempre stare seduti nella terra!", "Ma come fai a reggere tutti quei massi!\n\nSono perfetti. Quasi tutti hanno pure un bel lato piatto. Ora che li hai portati fin qui, possiamo spingerli nella terra proprio dove li vogliamo.\n\nGrazie, {name}!", 0xf790b060, 0xc71bf5e0, 0x831d0833, 0x1382164d, 0xc29549c2, "....." },
  [97327] = { "Borselli degli Zannanera", "Entra nella ⟦Blackmaw Hold=Tana degli Zannanera⟧ e recupera $N1 Borsello degli Zannanera per Ekkal alle ⟦Ruins of Eldarath=Rovine di Eldarath⟧ ad Azshara.", "Mi spezza il cuore ammetterlo, ma i miei fratelli e sorelle all'interno della ⟦Blackmaw Hold=Tana degli Zannanera⟧ sono irrimediabilmente corrotti.\n\nSe mi porti alcuni dei loro effetti personali, posso almeno dare alle loro famiglie qualcosa con cui ricordarli. Ogni fagotto che recupererai sarà un simbolo del tuo servizio al mio popolo.", nil, nil, 0xe558c49d, 0x560604f0, 0x01e4835e, nil, nil, "...mm" },
  [97328] = { "Qualcosa di valore", "Recupera $N1 Stolen Shipment dalle ⟦Ruins of Zul'Kunda=Rovine di Zul'Kunda⟧, nella Valle di Rovotorto, e porta il carico a qualcuno alla ⟦Booty Bay=Baia del Bottino⟧.", "<Frugando tra i rottami lasciati da un terribile schianto di zeppelin proprio qui sopra, trovi le tracce di un grosso carico di rifornimenti, saccheggiato da tempo di tutto ciò che aveva valore. Persino le etichette di spedizione sono state strappate e fatte a brandelli: su una si leggono a malapena le parole \"⟦Booty Bay=Baia del Bottino⟧\".\n\nInnumerevoli impronte a due dita e diverse chiazze di terra smossa portano tutte verso delle rovine a nord-ovest.>", "Hai l'aria confusa. Ti sei smarrit<o/a>?", "Dici che tutto questo è caduto da uno zeppelin precipitato a nord della giungla e che i troll Scalporosso ci hanno messo le mani sopra? Doveva arrivare a Porto Polveraccesa SEI SETTIMANE fa! Abbiamo persino stretto un accordo con Grom'gol per usare la loro torre per zeppelin per spedizioni accelerate!\n\nMi chiedevo perché Ronzafischio mi mandasse lettere sarcastiche. Non avremmo mai dovuto lasciare Zimmix al volante dopo quello che è successo l'ultima volta.\n\nFantastico. Semplicemente fantastico. Prendi questo e vattene, devo presentare richieste di risarcimento assicurativo.", 0xd56cd924, 0x19d4694d, 0xa7fe74f8, 0x620ef597, 0x67ff9a15, "....." },
  [97329] = { "Dov'è la chiave?", "Porta a Zimmix Sputterspark la ⟦Primitive Key=Chiave Primitiva⟧ presa ai troll delle Rovine di Zul'Kunda, nella Valle di Rovotorto.", "Tu! Sì, tu! Vieni qui, abbassa la voce!\n\nHo fatto un pasticcio enorme. Ero riuscito a strappare un affarone per usare la torre degli zeppelin della ⟦Booty Bay=Baia del Bottino⟧ per le consegne rapide, e proprio sulla prima rotta ho visto un uccello gigante... ehm, mi hanno ABBATTUTO, proprio qui a est!\n\nSono sopravvissuto allo schianto, purtroppo, ma prima ancora di svegliarmi mi stavano già trascinando per le orecchie! Ora sono circondato da troll assetati di sangue e chiuso in una gabbia!\n\nSenti, mi serve solo la chiave, d'accordo? Posso scappare da solo.", "Senti, mi piaci e tutto, ma il fatto che tu stia qui in giro ci fa sembrare sospetti! Se non hai la chiave allora, non so, VAI A PRENDERLA!\n\nPer favore?", "È quella la chiave?\n\n<Zimmix si lancia in avanti contro la parte anteriore della gabbia e tenta ripetutamente di sottrarti la chiave.>\n\nDammela e basta!", 0x4cd8cc0a, 0x11d8de27, 0x2fef21bb, 0x3223e635, 0x808cead6, "....." },
  [97331] = { "La grande fuga di Zimmix", "Scorta Zimmix Sputterspark lontano dalle ⟦Ruins of Zul'Kunda=Rovine di Zul'Kunda⟧, poi racconta al capitano del porto Malattracco, alla ⟦Booty Bay=Baia del Bottino⟧, che il salvataggio è riuscito.", "Aspetta, aspetta, non andartene ancora!\n\nLo so che ho detto che mi serviva solo la chiave, ma... be', mi hanno preso una volta, potrebbero rifarlo, no? Sono solo un goblin, e qui intorno ci sono centinaia di troll!\n\nNe hai già fatti fuori abbastanza per prendere questa chiave, quindi dovrebbe essere facile fare la guardia mentre ce la filiamo da qui, eh?", nil, "Oh, per tutto l'oro! Sei stat<o/a> TU a salvare Zimmix?\n\nIl tuo tempismo non poteva essere peggiore. Avevamo appena fatto un brindisi di festeggiamento pensando che finalmente ce lo fossimo tolti dai piedi per sempre, e abbiamo un'altra consegna critica in arrivo che deve ancora essere assegnata. Ovviamente lui sta già cercando di accaparrarsela e, ovviamente, devo oppormi o rischiamo un altro dei suoi grandi disastri!\n\nUn consiglio: se vedi un goblin intrappolato in una gabbia, probabilmente se lo merita. La prossima volta lascialo lì.", 0x27ec33fb, 0x6aebab8a, 0xad346a39, nil, 0x450047dc, "...m." },
  [97332] = { "Doppia fiducia mal riposta", "Consegna il Pacco Riordinato Due Volte al capitano del porto Ronzafischio a Porto Polveraccesa, nelle Radure del Fiume.", "Per quanto non mi piaccia quel tizio, ho sentito cosa fa la tribù degli Scalporosso ai suoi prigionieri, e non è bello. Sono contento che Zimmix se la sia cavata.\n\nTuttavia ho un'altra consegna urgente e NON mi fido di lui per farsene carico. Il problema? Nessun altro sarà disponibile per prenderla prima di lui. Tu, però, hai recuperato un carico perduto e un goblin catturato, quindi da quaggiù mi sembri piuttosto affidabile.\n\nC'è qualche possibilità di convincerti a portare questo a Ronzafischio al Porto Polveraccesa?", "Non vedi che sono occupato?", "Eh? Cosa mi porti?\n\n<Ronzafischio sbircia dentro la cassa e la sua espressione si illumina subito di sorpresa.>\n\nGuarda qua! Malattracco alla fine ce l'ha fatta. Ci sono volute solo una lettera feroce e pagare il corriere per minacciarlo, per fargli capire il concetto. Chissà quale sarà la sua scusa. Il capitano della nave è stato catturato? Si è schiantato uno zeppelin?\n\nHaha, ti immagini? Qui intorno non abbiamo nemmeno una torre per zeppelin!\n\nSembra che tu ne abbia passate tante per consegnare questo, quindi tieni una ricompensa.", 0x01a0c8e6, 0x47bdbd9a, 0x3c8eb415, 0x94a743f5, 0x615a3ccb, "....." },
  [97378] = { "Scaglia Specchiata", "Porta l'Ala di Scaglia Specchiata a ⟦Melor Stonehoof=Melor Zoccolo Granitico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧.", "{name}, hai dimostrato forza e dedizione come <cacciatore/cacciatrice> e sono colpito dal tuo coraggio. È solo per questo che ti offro questa caccia.\n\nUn serpente del vento caccia lungo una strada al largo della costa di Feralas e ha teso agguati ai viaggiatori, lasciando i loro cadaveri sparsi lungo la strada. È chiaro che non caccia per necessità. È una creatura che non condivide più la benedizione della Madre Terra.\n\nIl serpente del vento Scaglia Specchiata ha il suo covo ai piedi della cascata lungo la costa di Feralas.", nil, nil, 0x40644be3, 0x8b3be0d3, 0xebdb1247, nil, nil, "...mm" },
  [97386] = { "L'offesa di Grom'gol", "Il ⟦Commander Aggro'gosh=Comandante Aggro'gosh⟧ dell'accampamento base di Grom'gol vuole che tu uccida degli ogre al Tumulo degli Ogre Mosh'ogg.", "{name}! Il tuo arrivo è tempestivo, come sempre.\n\nHai fornito un valido aiuto alla difesa di Grom'gol e te ne siamo grati. Dopo la tua recente spinta contro gli ogre nelle vicinanze, abbiamo mandato un esploratore per vedere se ce ne sono altri là fuori che potrebbero tentare di vendicarsi di noi. A quanto pare c'è una caverna molto a est che hanno rivendicato come tugurio.\n\nRaduna un amico o due e fai capire molto chiaramente che non tollereremo un'altra minaccia al nostro insediamento, ora e mai!", nil, nil, 0x58c910e7, 0x93dbc428, 0x7aba1639, nil, nil, "...mm" },
  [97403] = { "Devastatori bicefali", "Uccidi $N1 Devastatore Ventofreddo e torna da Rilan Howard nel nord di ⟦Winterspring=Fontefredda⟧.", "Queste chimere sono uno scherzo crudele. Due lingue, entrambe immonde, che ringhiano gelo e fame. Come se questa landa desolata avesse bisogno di altri denti.\n\nQuesta radura è tutto ciò che abbiamo, costantemente sopraffatta dalle tempeste prima che possiamo stabilirci altrove. I Devastatori Ventofreddo a due teste ci girano intorno, mettendo alla prova la nostra determinazione, sprecando il nostro tempo.\n\nPassiamo più ore a respingerli che a costruire qualcosa di valore.\n\nSfoltiscili. Spezza la loro presenza qui. Con meno bestie in agguato, potremmo ancora ricavare qualcosa di duraturo da questa landa ghiacciata.", nil, nil, 0x3ee999fd, 0x07399a0e, 0xda11bfa6, nil, nil, "...mm" },
  [97404] = { "Troppo cattivo da sopportare", "Uccidi le vecchie matriarche denterotto, Kuroma e Kamuro, e riporta le loro teste a Sarna Cornobruno.", "Ci sono due vecchie matriarche, ben oltre i loro cicli di allevamento dei cuccioli. Forse sono sorelle. Potrebbero anche essere due orse affini che hanno condiviso un simile trascorrere di stagioni.\n\nIndipendentemente da ciò che le ha unite, hanno ancora una ferocia e una volontà di vivere che impongono rispetto. Cercare di allestire un campo come questo è stato difficile per noi, con queste due Denterotto canute.\n\nPortami le teste di Kuroma e Kamuro, e cerca di porre fine a loro in modo rapido, abile e con misericordia.", nil, nil, 0x9266c688, 0xa0d7ef41, 0x45090772, nil, nil, "...mm" },
  [97405] = { "Lamentele per il rumore", "⟦Knaz Blunderflame=Knaz Fiammacurva⟧ vuole che tu uccida $N1 Creamagie Mosh'ogg, $N2 Guerrafondaio Mosh'ogg, $N3 Mazzuolatore Mosh'ogg e $N4 ⟦Mosh'Ogg Shaman=Sciamano Mosh'ogg⟧ al Tumulo degli Ogre Mosh'ogg.", "Gnaz laggiù sta costruendo quella trappola mortale per la competizione fino a Kalimdor. Gli ho detto che il suo armeggiare costante a tarda notte fa un sacco di rumore, e ieri notte ho visto un ogre sbirciare con la sua brutta testa da dietro quell'albero!\n\nÈ ossessionato dall'ambizioso sogno di vincere i Campionati della ⟦Mirage Raceway=Pista dei Miraggi⟧, ma io sono ossessionato dal non essere sbranato a morte! Ti prego, vai oltre la collina a nord e assicurati che smettano di ficcare il naso da queste parti.", nil, "È fatto? Accidenti, spero di sì. Non credo che Gnaz si renda conto che se facciamo arrabbiare abbastanza gli ogre, marceranno fin quassù e faranno a pezzi la sua piccola macchina da corsa!\n\nGrazie, ora posso tirare un sospiro di sollievo.\n\n<Knaz, in effetti, tira un sospiro di sollievo.>", 0xf5dba294, 0x634f040e, 0x4f39b5e6, nil, 0x1965a3ca, "...m." },
  [97411] = { "Una proposta sincera", "Ottieni 15 Campione di Veleno di Silitide e 20 monete d'oro e portali, insieme a un paio di ⟦Lightforge Bracers=Bracciali della Forgia della Luce⟧, a Mokvar a Orgrimmar.", "Salve, {class}! Dal tuo portamento si vede che hai visto e fatto molto in questo mondo. Eppure scommetto che non hai mai visto un pezzo d'armatura come questo.\n\nFammi un piccolo favore e sarò disposto a scambiartelo con un normale paio di bracciali.\n\nMi serve un campione consistente di veleno estratto dai ragni e dagli scorpioni che abitano ⟦Silithus=Silitus⟧. Portamelo insieme a qualche moneta d'oro e farò lo scambio.", nil, nil, 0x5744ae45, 0x30ac6ac9, 0xea675b9d, nil, nil, "...mm" },
  [97412] = { "Giusto compenso", "Porta una ⟦Lightforge Belt=Cintura della Forgia della Luce⟧ e un paio di ⟦Lightforge Gauntlets=Guanti Lunghi della Forgia della Luce⟧ a Mokvar a Orgrimmar.", "Ti sei dimostrat<o/a> una persona molto affidabile, {name}. Per quanto confidi che mi aiuterai a uscire da questa situazione, sarebbe saggio da parte mia ricompensarti in base alle tue prestazioni.\n\nPer ora scambierò la tua cintura e i tuoi guanti. Se porteremo entrambi a termine l'impresa, ti renderò disponibili anche gli altri pezzi.", nil, nil, 0x467758ec, 0x04e05cab, 0xd0d70463, nil, nil, "...mm" },
  [97413] = { "Le parole d'addio di Anthion", "Torna da Mokvar a Orgrimmar con ⟦Lightforge Boots=Stivali della Forgia della Luce⟧, ⟦Lightforge Legplates=Gambali Corazzati della Forgia della Luce⟧ e ⟦Lightforge Spaulders=Guardaspalle della Forgia della Luce⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Nella nostra avidità lo dividemmo stoltamente in tre parti, ignorando la maledizione che ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è ricomporre l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza per trovare i pezzi rimanenti. Parlagli delle ricompense che hai concordato.\n\nIo, per una volta, riposerò in pace. Ti auguro la migliore fortuna; ne avrai bisogno fino all'ultima goccia!", nil, nil, 0x4e493fc8, 0x50eae694, 0xbf3e43cf, nil, nil, "...mm" },
  [97414] = { "Il meglio per ultimo", "Consegna a Mokvar il tuo ⟦Lightforge Helm=Elmo della Forgia della Luce⟧ e il tuo ⟦Lightforge Breastplate=Pettorale Corazzato della Forgia della Luce⟧.", "Una storia davvero incredibile, {name}! Hai il mio ringraziamento e la sentita gratitudine di tutti i coinvolti, te l'assicuro. Grazie ai tuoi sforzi siamo liberati dagli errori del nostro passato.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti sei decisamente guadagnat<o/a> e che apprezzerai davvero.", nil, nil, 0x48402900, 0x462dd352, 0xf3ed443f, nil, nil, "...mm" },
  [97420] = { "Riduci, riusa, riconcilia", "Procurati $N1 Drums of Crude Oil dagli impianti della S.P.R. & Co. al ⟦Lake Nazferiti=Lago Nazferiti⟧, poi torna da ⟦Knaz Blunderflame=Knaz Fiammacurva⟧ nella Valle di Rovotorto.", "Ho un favore da chiedere a qualcuno, e tu hai l'aria di uno che aiuta!\n\nVedi questa bellezza? Non è una meraviglia? È il mio nuovo bolide da corsa, progettato e costruito tutto da me, perché QUALCUNO non ha voluto aiutarmi. Voglio portarlo alle gare di ⟦Thousand Needles=Millepicchi⟧, ma gli serve una spintarella in più.\n\nOra, io sono troppo bello per essere un goblin, e so bene che non c'è da fidarsi della loro tecnologia, ma so che la S.P.R. & Co. ha trovato oro liquido laggiù al lago. Sono sicuro che non gli dispiacerà se tu, ehm, ne prendessi un po' in prestito. Non se ne accorgeranno nemmeno!", nil, nil, 0x4056755c, 0xc361c56c, 0x4d212a67, nil, nil, "...mm" },
  [97446] = { "Il tuo primo ⟦Riding Kodo=Kodo Cavalcabile⟧", "Ispeziona i Kodo Cavalcabili per scegliere la tua prima cavalcatura.", "Ah, ti aspettavo, {class}. Sembra che i venti ti abbiano portato da me oggi. Sei qui in cerca di un kodo, giusto?\n\nIl kodo è una nobile bestia lenta all'ira e difficilmente troveresti un compagno più affidabile.\n\nOggi hai una scelta importante da fare. Tu e il tuo kodo viaggerete insieme per il mondo, quindi trova quello che ti parla. Non temere, qualunque scelta farai sarà quella giusta.\n\nVai a esaminare i kodo e torna da me quando avrai deciso.", nil, nil, 0x2f8c7c80, 0x9ca0fd73, 0xa07cac2b, nil, nil, "...mm" },
  [97447] = { "Una proposta sincera", "Ottieni 15 Campione di Sangue di ⟦Winterspring=Fontefredda⟧ e 20 monete d'oro e portali, insieme a un paio di Manette degli Elementi, a Deliana a ⟦Ironforge=Forgiardente⟧.", "Salute, {class}. Ho qualcosa che potrebbe interessarti.\n\nHo con me un'armatura simile a quella indossata da chi esercita la tua professione, ma di qualità molto superiore. Sarei disposto a scambiarti i bracciali con quelli ordinari in cambio di un piccolo favore.\n\nIl sangue delle fiere glaciali e degli orsi che abitano ⟦Winterspring=Fontefredda⟧ ha proprietà di cui al momento ho bisogno. Portamene un campione consistente insieme ai bracciali e a una piccola somma d'oro. Troverai che lo sforzo ne vale la pena.", nil, nil, 0x5744ae45, 0x9407c1a6, 0x9df430b9, nil, nil, "...mm" },
  [97448] = { "Giusto compenso", "Porta un Fascione degli Elementi e un paio di Guanti Lunghi degli Elementi a Deliana a ⟦Ironforge=Forgiardente⟧.", "Hai mantenuto la parola e hai portato il dispositivo costruito da Mux. Credo che una ricompensa sia dovuta, se voglio che tu resti interessat<o/a> a salvarmi la pelle. Portami la cintura e i guanti lunghi che desideri potenziare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.", nil, nil, 0x467758ec, 0xad7c808b, 0x35c57e0b, nil, nil, "...mm" },
  [97449] = { "Le parole d'addio di Anthion", "Torna da Deliana a ⟦Ironforge=Forgiardente⟧ con ⟦Boots of Elements=Stivali degli Elementi⟧, ⟦Kilt of Elements=Kilt degli Elementi⟧ e ⟦Pauldrons of Elements=Paraspalle degli Elementi⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Nella nostra avidità lo dividemmo stoltamente in tre parti, ignorando la maledizione che ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza per trovare i pezzi rimanenti. Parlale delle ricompense che hai concordato.\n\nIo, per una volta, riposerò in pace. Ti auguro la migliore fortuna; ne avrai bisogno fino all'ultima goccia!", nil, nil, 0x4e493fc8, 0x1c942504, 0x84b4d2d2, nil, nil, "...mm" },
  [97450] = { "Il meglio per ultimo", "Consegna a Deliana la tua ⟦Coif of Elements=Maschera degli Elementi⟧ e la tua ⟦Vest of Elements=Maglia degli Elementi⟧.", "Che storia incredibile, {name}! Hai il mio ringraziamento e la sentita gratitudine di tutti i coinvolti. Ora forse riuscirò a dormire la notte con entrambi gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti piacerà molto.", nil, nil, 0x48402900, 0xd80dbd04, 0x03db6ed6, nil, nil, "...mm" },
  [97453] = { "Erbacce da falciare", "Uccidi $N1 Erbaccia Carnivora a sud di Grom'gol, poi avvisa la madre di Gemmil.", "Ciao, puoi aiutarmi?\n\nI miei genitori mi hanno finalmente lasciato venire con loro in questa grande giungla e mi hanno persino fatto raccogliere qualche pianta subito fuori dai cancelli. Sto cercando di studiare erboristeria per diventare un giorno alchimista!\n\nComunque, avevo quasi riempito lo zaino quando un gruppo di enormi erbacce arrabbiate è spuntato dal nulla e ha iniziato a sputarmi addosso!\n\nMe la sono filata e sto bene, ma ora non mi lasciano più giocare fuori dal campo. Puoi renderlo sicuro per me e poi dirlo a mia mamma?", nil, nil, 0xc436e8d8, 0x3f3064d7, 0x6bfd1ba8, nil, nil, "...mm" },
  [97485] = { "Le tradizioni del Picco", "Compra un ⟦Bundle of Herbs=Mazzo di Erbe⟧ da Nida, che vende erbe, un Bundle of Cedar Twigs da Nata, che vende materiali per incantamento, del ⟦Sinew Thread=Filo di Tendine⟧ da Mahu, che vende materiali per conciatura, e una ⟦Ceremonial Flint and Tinder=Pietra Focaia ed Esca Cerimoniali⟧ da Naal, che vende materiali per cucina.\n\nUnisci gli oggetti e spargi l'incenso dall'Hunter's Rise.", "Che An'she ti benedica, amico.\n\nNoi tauren abbiamo la tradizione di spargere incenso ai venti, e speravo che ti interessasse onorarla.\n\nDovrai preparare l'incenso comprando le erbe da Nida, il cedro da Nata, il filo di tendine da Mahu sul terrazzo di mezzo, e la pietra focaia ed esca cerimoniale da Naal sul terrazzo più alto. Quando avrai questi oggetti, uniscili e spargili dalla scogliera rivolta a sud dell'Hunter's Rise.\n\nTroverai una stuoia e dell'incenso nel luogo della cerimonia.", "Ci sono molte occasioni in cui si può scegliere di spargere incenso ai venti. Potresti chiedere alla Madre Terra di vegliare su qualcuno, benedire una caccia, celebrare un'occasione o perfino cercare la guida dei nostri antenati.\n\nOppure potrebbe essere tutt'altro.\n\nAnche se il gesto si compie con reverenza, non è un rito strettamente cerimoniale. Di solito si seguono alcuni passi tradizionali, ma molte tribù hanno usanze diverse.", "Hai fatto bene, amico.\n\nTi ringrazio per aver dedicato del tempo a una delle nostre tradizioni più antiche, {name}. Spero che nei tuoi viaggi troverai tante occasioni per cui rendere grazie.\n\nSe mai vorrai ripetere il rito, potrai ricomprare gli ingredienti che ti ho mandato a raccogliere.\n\nVa' con il calore di An'she.", 0x8de39461, 0x5aef4be7, 0xd944b43a, 0xb3960157, 0x40cd2a71, "....." },
  [97490] = { "Fermare la grandine", "Cerca nelle colline meridionali di ⟦Winterspring=Fontefredda⟧ il gigante noto come Malagrandine e recupera il muschio gelido che gli cresce addosso.", "Ehi amico, sto cercando di smontare un po' di rottami per avere pezzi per la mia macchina, ma le cose si stanno scaldando troppo.\n\nSo cosa stai pensando: ⟦Winterspring=Fontefredda⟧? Si scalda? Come vedi, il mio frantumatore e il mio ridistributore sono in funzione, ma tossicchiano forte! Ciò di cui hanno davvero bisogno è qualcosa che li raffreddi e che non si sciolga, non scivoli e non bruci.\n\nSulle colline meridionali si aggira un gigante cattivo che chiamiamo Malagrandine. Metti fine a Malagrandine e portami il muschio gelido che cresce sulle sue rupi.\n\nPotrebbe funzionare per me!", nil, nil, 0xe393571a, 0x63f1f929, 0x5040f785, nil, nil, "...mm" },
  [97530] = { "Tributi ai Mazzaduna", "Il ⟦Security Chief Bilgewhizzle=Capo della Sorveglianza Segachiodi⟧ di ⟦Steamwheedle Port=Porto degli Spargifumo⟧, a Tanaris, vuole che tu recuperi un braccialetto particolarmente lucido perso vicino al complesso degli ogre Mazzaduna.", "Una carovana di mercanti ha preso una svolta sbagliata nel deserto ed è stata assalita dagli ogre Mazzaduna. L'unico motivo per cui sono sopravvissuti è che hanno gettato in mare parte del carico per distrarre i bruti.\n\nDeve essere che questo mercante ha amici tra i pezzi grossi che gestiscono navi e zeppelin, perché ora vogliono che sia IO a recuperare ciò che si è perso.\n\nSono bloccato qui a lavorare. Ma se TU vedi un bel braccialetto luccicante mentre picchi gli ogre, ne varrà la pena per te.", nil, nil, 0x38753845, 0xbddf478b, 0x7e7d1117, nil, nil, "...mm" },
  [97534] = { "Faccende sabbiose", "Quinn vuole che tu recuperi $N1 Detriti del Deserto e torni da lei a ⟦Gadgetzan=Meccania⟧.", "Psst, vuoi sapere una cosa? È più facile fare profitto in un posto come questo di quanto pensi... tutto sta nel sapere come fare marketing! Ho visto cosa fanno questi smanettoni quando mettono le mani su qualcosa che pensano di poter trasformare in una cella a combustibile.\n\nMeglio ancora se brilla ancora o sbuffa vapore.\n\nPerché non facciamo un accordo? Riporta qualche pezzo che cade dalle loro macchine nel deserto, e io ti rimborso una parte dei soldi che ricavo rivendendo i rottami ai demolitori!", nil, nil, 0x458c5266, 0x469a7416, 0xe621a6b5, nil, nil, "...mm" },
  [97536] = { "Rifiuti gnomeschi", "⟦Jhordy Lapforge=Jhordy Saldapinza⟧ vuole che tu torni da lui dopo aver scaricato la Cassa di Scorie Radioattive nel deserto di Tanaris, a distanza di sicurezza da ⟦Gadgetzan=Meccania⟧ e dagli altri rifiuti.", "Il Trasportatore di Materia ha richiesto sperimentazioni per essere messo a punto. Sono stati fatti molti test su ogni sorta di materiale... con esiti diversi! Alcuni dei risultati non ci sono più. Altri sono diventati pericolosamente carichi!\n\nQuesti oggetti sottoposti emettono un'energia che brucia se resti vicino troppo a lungo. Quasi come se fossero stati caricati con un anno di potere del sole del deserto.\n\nPrendi questa Cassa di Scorie Radioattive e svuota il contenuto nella sabbia a distanza di sicurezza dalla città e da altri rifiuti.", nil, "Come sono le tue mani? Riesci ancora a sentire le dita?\n\nNon preoccuparti, dovrebbe passare presto. Ora possiamo osservarli da una distanza di sicurezza!\n\nGrazie, {name}.", 0xc60ec55d, 0x53ea08c2, 0xad44b91a, nil, 0xe86fb327, "...m." },
  [97538] = { "Pigmenti per i colori", "⟦Tah Winterhoof=Tah Zoccolo Artico⟧, a ⟦Thunder Bluff=Picco del Tuono⟧, vuole $N1 ⟦Mirkweed Pods=Baccelli di Alga Torbida⟧ dal ⟦Mirkfallon Lake=Lago Mirkfallon⟧.", "Salute, amico. Posso chiederti un favore? Ho appena finito il pigmento rosso per i miei colori, e cerco qualcuno con gli zoccoli più giovani dei miei che faccia per me il lungo viaggio fino alle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.\n\nA metà del passo montano c'è un grande lago rotondo, il ⟦Mirkfallon Lake=Lago Mirkfallon⟧, nelle cui acque cresce una pianta unica. I baccelli di questa pianta, il mirkweed, diventano di un rosso vivo una volta seccati. Raccogli per me i baccelli di questa pianta e ti ricompenserò bene per la fatica.", "Sei tornat<o/a>! Sei riuscit<o/a> a trovare i baccelli di alga torbida nel ⟦Mirkfallon Lake=Lago Mirkfallon⟧?\n\nNoi tauren usiamo il pigmento di questa pianta nei nostri colori da generazioni, quindi qualsiasi quantità tu riesca a portare sarà apprezzata. Anche se ci sono molti modi per ottenere un pigmento rosso, trovo che l'alga torbida dia la tonalità più ricca e vibrante tra i metodi che conosco.", "Ah, grazie, {name}.\n\nSignifica molto per me che tu ti sia spint<o/a> fin laggiù per quella che deve sembrare un'idea banale di un vecchio tauren, ma con la tua gentilezza avrò abbastanza pigmento per il resto della stagione.\n\nGrazie per aver sostenuto il mio sostentamento, e mi impegnerò a creare qualcosa di magnifico con i pigmenti che hai portato.", 0xaa3850ee, 0x98b0df48, 0xd373bd5c, 0x3ae2b31d, 0xa8ab7c11, "....." },
  [97539] = { "Suture di seta", "Riporta 12 ⟦Surgical Spidersilk=Seta di Ragno Chirurgica⟧ al dottor Gregory Victor a ⟦Hammerfall=Requie del Martello⟧, negli ⟦Arathi Highlands=Altopiani d'Arathi⟧.", "Questo accampamento è lasciato a marcire. I danni dell'assedio restano lì, senza riparazioni, come se l'incuria fosse una regola. Non permetterò lo stesso degrado qui. L'infermeria risponde a me, e intendo tenerla in funzione.\n\nSiamo quasi senza scorte. Mi serve altro materiale, abbastanza da tenere in piedi lavoratori e guardie.\n\nIn caso di necessità, con la seta di ragno ritorta si può fare una sutura da campo molto efficace.\n\n{class}, portamene un po' dai ragni che si aggirano per questi altopiani.", nil, nil, 0xdf5a915e, 0x4b00338c, 0x5c3dc6d2, nil, nil, "...mm" },
  [97540] = { "Oasi", "Mostra al neo-dissetato Tooga la strada per tornare da sua moglie, Torta.", "Oh, quest'acqua dolce ha un odore così buono...\n\nMi fermo un momento a fare una nuotata veloce e a bere.", nil, nil, 0x77d8fe0c, 0xec717c40, 0xf2469823, nil, nil, "...mm" },
  [97558] = { "Pelli per i Reietti", "Porta a Shelene Rhobart $N1 Duskbat Wing Membrane, $N2 Darkhound Hide e $N3 ⟦Vile Fin Murloc Skin=Pelle di Murloc Pinnainfame⟧.", "C'è un aspetto della non morte di cui nessuno parla: cosa succede quando veniamo feriti. Come guarisce la pelle di un non morto?\n\nBe', non guarisce.\n\nLa nostra è una vita maledetta, {name}. Dobbiamo prendere dai vivi per prolungare la nostra esistenza.\n\nQuando subiamo una ferita dobbiamo sostituire la pelle, e di solito questo vuol dire pelli di animali. Visto che spessori diversi si adattano meglio a punti diversi del corpo, la varietà è fondamentale!\n\nPortami le membrane delle ali di un pipistrello del vespro, le pelli di un segugio oscuro e la pelle di un murloc Vile Fin.", "Hai raccolto la pelle che ti ho chiesto? Le nostre scorte si stanno esaurendo.\n\nPuò sembrare strano chiedere pelle di murloc, ma funziona bene per le membrane interne o per superfici come guance e bocca.\n\nAllo stesso modo, le membrane delle ali dei pipistrelli del vespro sono particolarmente adatte alle zone più delicate, come il viso o le dita. Evitano che la pelle sia troppo... spessa.", "Ah, eccellente! Grazie per averle procurate. Ti prometto che saranno usate a dovere.", 0x09dcf31d, 0x19613344, 0x932d29f0, 0x6d509c4e, 0x35944081, "....." },
  [97583] = { "DIMENATI.", "Compra della ⟦Nutritious Slime Sludge=Fanghiglia di Melma Nutriente⟧ e torna dalla melma vivace che hai fatto tua amica. Se sembra stanca, prova di nuovo a ballare con lei per attirare la sua attenzione.", "<La piccola melma sembra felicissima e cerca di imitare i tuoi movimenti mentre balli. Però comincia ad avere l'aria stanca.\n\nLa piccola melma si sposta sopra un po' di poltiglia e la assorbe, e sembra un po' rinvigorita.\n\nPare che tutto questo ballare l'abbia sfinita. Forse qualcuno nei canali di ⟦Undercity=Sepulcra⟧ vende altra di questa poltiglia nutriente?>", "<La melma sembra osservarti con interesse.>", "<La melma freme di nuova energia. Sembra voler seguirti, ora che ti associa al cibo.>", 0x196f6916, 0x0ed19c12, 0x943783d3, 0xd43a8960, 0xc2a642e0, "....." },
  [97617] = { "Controlli di sicurezza", "Recupera $N1 Manufatto Inesplorato, un Casco da Minatore della ⟦Explorers' League=Lega degli Esploratori⟧ e una Zappa Intatta e portali a Dorgaron al confine tra Loch Modan e le ⟦Badlands=Maleterre⟧.", "Salve, hai l'aria di una persona disponibile.\n\nMi chiamo Dorgaron e sono della ⟦Explorers' League=Lega degli Esploratori⟧. Non abbiamo avuto molta fortuna con gli scavi nelle ⟦Badlands=Maleterre⟧, ma so benissimo che ci sono artefatti da trovare e raccogliere!\n\nPrima di poter convincere il capo a lasciarci mandare un'altra squadra quaggiù, devo dimostrare che i siti di scavo sono sicuri E che non sono stati ripuliti.\n\nSe ti trovi a sud, raccogli qualche artefatto ragionevolmente intatto e un po' di attrezzatura avanzata che non è stata ancora distrutta.", "Allora?", "Fantastico! È più che sufficiente per convincere a rimandare gente nelle ⟦Badlands=Maleterre⟧. So che tutti hanno gli occhi puntati su Uldaman vera e propria, ma non possiamo lasciare che questo ci distragga dall'inevitabile ricchezza di scoperte che attende tutto intorno alle pianure.\n\nSuppongo che tu abbia scacciato chiunque o qualunque cosa avesse occupato quei luoghi, giusto? Spero proprio di sì, altrimenti il capo mi staccherà l'orecchio per aver mentito sulla loro sicurezza...", 0xa657373f, 0x42920691, 0xff6fff61, 0x04ce131b, 0x9ece4967, "....." },
  [97663] = { "Scorte e studi", "Uccidi gli ogre nella Piana della Polvere per ottenere le Scorte Rubate di Mus'hale e usale per fare i ricalchi delle incisioni sulla pietra nei dintorni, poi torna da Mus'hale a Kargath.", "Ho notato alcune rocce che sembravano insolite nella Piana della Polvere. A un esame più attento, ho visto che avevano delle incisioni! Non ho resistito alla tentazione di farne dei ricalchi da studiare più tardi.\n\nGli ogre vicini hanno notato la mia presenza e, prima ancora che potessi reagire, ero già sotto le cure del locandiere, con un terribile mal di testa.\n\nOra ho perso tutte le mie provviste e sono senza materiale di studio mentre mi riprendo. Puoi avventurarti a est in cerca del mio zaino e fare tu i ricalchi delle incisioni?", nil, nil, 0x3dd5012d, 0x055fbd2d, 0xf1936994, nil, nil, "...mm" },
  [97821] = { "Specchio del Miraggio", "Trova qualcuno nelle ⟦Badlands=Maleterre⟧ che possa essere interessato a questa scoperta.", "<Alla morte dell'elementale, dal suo nucleo è caduta una reliquia che brillava nella sabbia.\n\nMentre la inclini tra le mani, il riflesso dell'ambiente circostante la nasconde alla tua vista. Solo quando hai visto una superficie incrinata che deformava il riflesso è tornata chiaramente visibile.\n\nForse qualcuno sarebbe interessato a questa scoperta.>", nil, nil, 0x6847d38a, 0x08baf57e, 0x57aa5b31, nil, nil, "...mm" },
  [97883] = { "La fine dell'⟦Horde=Orda⟧ Oscura", "Porta la ⟦Head of Rend Blackhand=Testa di Rend Manonera⟧ al ⟦Major Mattingly=Maggiore Mattingly⟧ a ⟦Stormwind=Roccavento⟧.", "Porta la testa di Manonera al ⟦Major Mattingly=Maggiore Mattingly⟧ alle porte della città. Lui e i suoi uomini proclameranno la grande vittoria che hai ottenuto oggi, così che il resto dell'⟦Alliance=Alleanza⟧ possa trarne ispirazione.\n\nHai reso un grande servigio oggi, {name}. Uno che tutti ricorderanno, compresi i nostri nemici.", nil, nil, 0x3409b38a, 0xc68501b7, 0x1e336650, nil, nil, "...mm" },
  [97884] = { "L'Armeria di Radura Solare", "Raggiungi ⟦Sunnyglade=Radura Solare⟧, nelle ⟦Riverglades=Radure del Fiume⟧, e recupera il tomo ⟦Tremayne Family Blacksmithing Techniques=Tecniche di Forgiatura della Famiglia Tremayne⟧.", "Sembri un {race} in salute e in forze. Cerco qualcuno che vada a ⟦Sunnyglade=Radura Solare⟧, nelle ⟦Riverglades=Radure del Fiume⟧, appena a nord delle ⟦Redridge Mountains=Montagne Crestarossa⟧.\n\nUn tempo la mia famiglia possedeva un'armeria laggiù. Immagino che ora sia un guscio bruciato, ma vorrei che recuperassi un tomo con le antiche tecniche di forgiatura delle armature della mia famiglia. Era custodito nel seminterrato, quindi spero che non sia ancora stato rovinato dalle intemperie.", "Ah, sei tornat<o/a>. Sei riuscit<o/a> a recuperare il tomo della mia famiglia? In che stato è la Radura Solare?\n\nL'ultima volta che ho visto la mia vecchia città, stava bruciando fino a ridursi in cenere.\n\nMi sono unito all'esercito di ⟦Stormwind=Roccavento⟧ e ho viaggiato fin quassù a Lordaeron e sono morto nella seconda guerra, quindi non ho mai avuto occasione di tornare. Ho sentito di sforzi per ricostruire la Radura Solare, ma non sono sicuro che ci siano mai riusciti.", "Grazie, {class}. Dubito molto che sarei sopravvissuto al viaggio o alla destinazione, considerando lo stato in cui dici che si trova ora la Radura Solare.\n\nQuesto tomo è esattamente ciò di cui avevo bisogno. Sono felice di dire che ci sono anche tutte le pagine.\n\nForse posso imparare un nuovo mestiere nella non morte. Mi darebbe almeno un'abilità da affinare per il resto della mia non vita.", 0xdb50c496, 0x3df7946f, 0xb9bb6bfc, 0x6ff54db5, 0x5bf0abfb, "....." },
  [97891] = { "Corriere di pozioni puntuale", "Porta la ⟦Unstable Potion=Pozione Instabile⟧ al dottor Martin Felben, all'Apothecarium, entro il tempo limite.", "Tu! Presto, devi portare questa pozione oltre il canale di melma, al dottor Martin Felben, all'Apothecarium!\n\nSi conserva per pochissimo tempo, e no, non posso andarci io: se provo a correre, le ginocchia mi scricchiolano e saltano via.\n\nUn altro delizioso effetto collaterale della non morte, a quanto pare.\n\nMa stiamo perdendo tempo! Ecco, prendi e vai!\n\n<Alessandro ti fa cenno di sbrigarti.>", nil, "Ah, meraviglioso! Aspettavo che arrivasse la pozione di Alessandro. Le ultime sei che ha mandato si sono destabilizzate per strada, ma tu sei arrivat<o/a> appena in tempo!\n\nEcco, prendi questo per il disturbo. Per ora è tutto, a meno che tu non abbia altri affari con me.\n\nIn caso contrario, togliti di torno, così posso continuare i miei esperimenti in pace.", 0x5ecd7075, 0x57e062c5, 0x38a757cf, nil, 0xad4dc35c, "...m." },
  [97894] = { "Affari ad Auberdine", "Controlla come sta ⟦Gorbold Steelhand=Gorbold Mandacciaio⟧ ad Auberdine, a ⟦Darkshore=Rivafosca⟧.\n\nBorgus ha parlato di una nave, al molo più a sud del porto di ⟦Stormwind=Roccavento⟧, che può portarti laggiù.", "Piacere di fare la tua conoscenza! Mi chiamo Borgus, della sola e unica famiglia Steelhand. Con uno Steelhand puoi sempre contare su un affare onesto!\n\nQualche settimana fa mio fratello Gorbold si è messo con una bancarella di mercanti ad Auberdine. C'è un sacco di soldi da fare rifornendo le navi, laggiù, credimi! Che fortunello.\n\nDa allora non ho più avuto sue notizie. Ti spiace controllare come sta, se vai da quelle parti?\n\nNel porto c'è una nave nuova che ti porterà dritto laggiù. Va' al molo più a sud: non puoi sbagliare!", nil, "Ti manda il vecchio Borgy? Pensa sempre a me.\n\nUn altro paio di mani qui ci farebbe proprio comodo. Con la recente tragedia gli affari si sono quasi fermati, e credo che tu possa aiutare a rimettere le cose a posto.", 0x05e986b2, 0xc51e34fa, 0x4f88604b, nil, 0xe4fd9705, "...m." },
  [97899] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Whuut a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0xc1f8026d, 0xf6c52c29, nil, nil, "...mm" },
  [97900] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con Dwukk a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, "Ecco fatto: ora puoi fabbricare una Mola per Affilare tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x16979ea3, 0xc5732bbb, 0x469a706e, nil, 0xe5c38af5, "...m." },
  [97901] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con Jhag a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xd5fb1529, 0xb4a29ffc, nil, nil, "...mm" },
  [97902] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con Mukdrak a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xcf977e31, 0x549b28c0, nil, nil, "...mm" },
  [97903] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Rawrk a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0xa11a2e39, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97904] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con ⟦Lau'Tiki=Lau'tiki⟧ vicino al ⟦Sen'jin Village=Villaggio di Sen'jin⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto, tu puoi creare tua Boccia per Pesci. Gente non tiene molto a accampamenti in centro città, quindi tu devi andare nella natura selvaggia se vuoi provarla.\n\nNessun accampamento è completo senza un falò, amico. Te ne serve uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Parla con qualcuno che può addestrarti nelle arti culinarie se non hai ancora imparato le basi.", 0xe0c1c700, 0x7cb6468b, 0x1bcf05fd, nil, 0x1f74bef2, "...m." },
  [97905] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con Jandi a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco qua, ora tu sai creare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace tanto che si piantano accampamenti in mezzo al paese, quindi tu devi andare nelle terre selvagge se vuoi provarla.\n\nNessun accampamento è completo senza un fuoco, amico. Te ne serve uno prima di allestire il tuo accampamento. Quasi tutti i cuochi ti insegnano ad accendere un fuoco. Passa da qualcuno che ti istruisce nell'arte culinaria, se le basi ancora non le hai imparate.", 0xd7cde71c, 0xdecd7cd7, 0xe0048777, nil, 0x37424fd5, "...m." },
  [97906] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con Karolek a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0x78212a11, 0x86e620e9, nil, nil, "...mm" },
  [97907] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con Krunn a ⟦Razor Hill=Tranciacolle⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora puoi fabbricare una Magnetite tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x7978666b, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97908] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con Thuwd a Orgrimmar per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0xd889c883, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97914] = { "Nuovi orizzonti", "Porta la ⟦Thundris' Letter=Lettera di Thundris⟧ a Baros Alexston, a ⟦Stormwind=Roccavento⟧.\n\nThundris ha parlato di una nave ad Auberdine che può portarti laggiù.", "Auberdine è un luogo modesto, {class}. Non sentirai pronunciare il suo nome tra le fronde di Darnassus. I più ricordano solo ciò che la Separazione ci ha tolto: le fiorenti città di ⟦Ameth'Aran=Ameth'aran⟧, ⟦Bashal'Aran=Bashal'aran⟧ e... Lathar'Lazal.\n\nEppure Auberdine resta nella loro ombra.\n\nVorrei che il nostro lavoro qui fosse riconosciuto. Una nuova nave ci collega al regno di ⟦Stormwind=Roccavento⟧, portando vita e rifornimenti sulle nostre coste. Ti prego di unirti al suo prossimo viaggio e di portare questa lettera a un umano di nome Baros Alexston.\n\nFai conoscere la nostra casa.", "Sento odore di mare su di te, amico!\n\n<Baros ride.>\n\nChe cosa ti porta a ⟦Stormwind=Roccavento⟧?", "<Baros apre la lettera e comincia a leggerla, mentre il sorriso gli svanisce dal volto.>", 0x47bf47e5, 0xe531658d, 0x0d17a10a, 0xccc0bbea, 0x30ab094d, "....." },
  [97915] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con l'alchimista Mallory nella ⟦Elwynn Forest=Foresta di Elwynn⟧, vicino a ⟦Stormwind=Roccavento⟧, per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", "Sì, posso insegnarti.", nil, 0x32f4ba12, 0x7a5b40ad, 0xf6c52c29, 0xf40d0e18, nil, "....m" },
  [97916] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con il fabbro Argus a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", "Sì, posso insegnarti.", "Ecco fatto, ora puoi creare una ⟦Sharpening Wheel=Mola per Affilare⟧ tutta tua. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, faresti bene a passare da qualcuno che possa istruirti nell'arte culinaria per imparare le basi.", 0x16979ea3, 0xbc0dd4f8, 0x469a706e, 0xf40d0e18, 0xe5c38af5, "....." },
  [97917] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con Betty Quin a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, "Ecco fatto, ora puoi creare il tuo Liuto Incantato. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x2e9b8c15, 0x1d55369b, 0xb4a29ffc, nil, 0x181203c3, "...m." },
  [97918] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con ⟦Sprite Jumpsprocket=Sprite Giramolla⟧ a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [97919] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Michelle Belle a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", "Posso insegnarti quando avrai acquisito un po' di abilità nella tua professione.", "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x872ca64f, 0x32ff3188, 0x558c53ee, 0x3a282524, "....." },
  [97920] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con Lee Brown vicino a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", "Posso insegnarti quando avrai acquisito un po' di abilità come <pescatore/pescatrice>.", "Ecco fatto: ora puoi fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0xc4adeb37, 0x1bcf05fd, 0x7ea339f7, 0x54727538, "....." },
  [97921] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con l'erbalista Pomeroy nella ⟦Elwynn Forest=Foresta di Elwynn⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0xd56c7091, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97922] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con Adele Fielder a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", "Sì, posso insegnarti.", "Ecco fatto, la tua tenda da campo. La maggior parte della gente non apprezza molto che si montino tende nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarla.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x40d05936, 0xd01e7cfe, 0x86e620e9, 0xf40d0e18, 0x01530ff6, "....." },
  [97923] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con ⟦Gelman Stonehand=Gelman Mandipietra⟧ a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x996abb28, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97924] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con ⟦Helene Peltskinner=Helene Scuoiapelli⟧ a ⟦Goldshire=Borgodoro⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", "Se hai un po' di abilità, posso insegnarti qualcosa.", "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0x7687adb0, 0x1755b1ba, 0xd511ff51, 0x98c24a76, "....." },
  [97925] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Eldrin al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧, nella ⟦Elwynn Forest=Foresta di Elwynn⟧, per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, "Ecco fatto, ora puoi creare il tuo Stendardo d'Adunata. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xde7f398c, 0x7350f5be, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [97926] = { "Arrangiarsi", "Porta la ⟦Alexston's Reply=Risposta di Alexston⟧ a ⟦Thundris Windweaver=Thundris Brigliavento⟧ ad Auberdine, a ⟦Darkshore=Rivafosca⟧.", "Vorrei che fosse così facile aiutare, {class}. Davvero.\n\nSe deciderai di passare più tempo nelle nostre terre, scoprirai che a molti manca tutto. Le casse di Roccavento non sono più quelle di un tempo, e quel che resta è distribuito con il contagocce.\n\nDai questa risposta all'anziano la prossima volta che lo vedi. Non è ciò che spera, ma è tutto quello che posso offrire per ora.", "Sei tornat<o/a>. Che notizie porti da ⟦Stormwind=Roccavento⟧?", "Brutte notizie davvero. Ti ringrazio comunque per aver fatto il viaggio.\n\nVisto che né ⟦Stormwind=Roccavento⟧ né Darnassus vengono in nostro aiuto, pare che il destino di Auberdine spetti a noi deciderlo.", 0xe4477319, 0xeee57b55, 0x5de57436, 0x33442a57, 0x68b57782, "....." },
  [97927] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Kray a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0x9fd6db54, 0xf6c52c29, nil, nil, "...mm" },
  [97928] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con ⟦Thrag Stonehoof=Thrag Zoccolo Granitico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0x0c123764, 0x469a706e, nil, nil, "...mm" },
  [97929] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con ⟦Mot Dawnstrider=Mot Alba Lunga⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0x907d3afc, 0xb4a29ffc, nil, nil, "...mm" },
  [97930] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con ⟦Twizwick Sprocketgrind=Twizwick Giramacina⟧ nella miniera della S.P.R. & Co., a Mulgore per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xcc961537, 0x549b28c0, nil, nil, "...mm" },
  [97931] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con ⟦Vira Younghoof=Vira Vento Salubre⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x86c85202, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97932] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con ⟦Uthan Stillwater=Uthan Acqua Ferma⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0x8745cbb5, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97933] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con ⟦Komin Winterhoof=Komin Zoccolo Artico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, nil, 0xd7cde71c, 0x2038d080, 0xe0048777, nil, nil, "...mm" },
  [97934] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con ⟦Chaw Stronghide=Chaw Pelle Forte⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, "Ecco fatto: una tenda da campo tutta tua. Alla gente non piace granché vedere tende montate in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x40d05936, 0xd9c41452, 0x86e620e9, nil, 0x01530ff6, "...m." },
  [97935] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con ⟦Brek Stonehoof=Brek Zoccolo Granitico⟧ a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, 0xab156797, 0x8ef0fff6, nil, nil, "...mm" },
  [97936] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con ⟦Yonn Deepcut=Yonn Taglio Fondo⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0xa1684cc3, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97937] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Vhan a ⟦Thunder Bluff=Picco del Tuono⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x21c61245, 0x49663bd1, nil, nil, "...mm" },
  [97938] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con ⟦Cyndra Kindwhisper=Cyndra Soffiodolce⟧ a Dolanaar per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Mana Well=Pozzo di Mana⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x32f4ba12, 0x4f3974b2, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97939] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con ⟦Elisa Steelhand=Elisa Mandacciaio⟧ ad Auberdine, a ⟦Darkshore=Rivafosca⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0xc4d92ccf, 0x469a706e, nil, nil, "...mm" },
  [97940] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con ⟦Alanna Raveneye=Alanna Occhiocorvo⟧ nella Radura dell'Oracolo, a Teldrassil per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0x491f3400, 0xb4a29ffc, nil, nil, "...mm" },
  [97941] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con Jenna Lemkenilli ad Auberdine, a ⟦Darkshore=Rivafosca⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xf8ad00a9, 0x549b28c0, nil, nil, "...mm" },
  [97942] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Byancie a Dolanaar per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0xae626583, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97943] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con ⟦Astaia=Kirolla⟧ a Darnassus per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto, ora puoi creare il tuo Boccia per Pesci. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xe0c1c700, 0x430360e0, 0x1bcf05fd, nil, 0x54727538, "...m." },
