  [97952] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con Basil Frye a ⟦Undercity=Sepulcra⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", "Sì, posso insegnarti.", nil, 0x16979ea3, 0xca12e161, 0x469a706e, 0xf40d0e18, nil, "....m" },
  [97953] = { "⟦Camping=Campeggio⟧ 101: Incantamento", "Parla con ⟦Vance Undergloom=Vance Sottocupo⟧ a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Enchanted Lute=Liuto Incantato⟧ per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0x24bb4093, 0xb4a29ffc, nil, nil, "...mm" },
  [97954] = { "⟦Camping=Campeggio⟧ 101: Ingegneria", "Parla con Graham Van Talen a ⟦Undercity=Sepulcra⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Reagent Bot=Robot dei Reagenti⟧ per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xa25e841e, 0x549b28c0, nil, nil, "...mm" },
  [97955] = { "⟦Camping=Campeggio⟧ 101: ⟦First Aid=Primo Soccorso⟧", "Parla con l'infermiera Neela a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, "Ecco fatto: ora puoi fabbricare un ⟦First Aid Kit=Kit di Primo Soccorso⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x6e7c255b, 0x85dce6c2, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97956] = { "⟦Camping=Campeggio⟧ 101: Pesca", "Parla con Clyde Kellen a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Fish Bowl=Boccia per Pesci⟧ per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto, ora puoi creare il tuo Boccia per Pesci. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xe0c1c700, 0x3f726cba, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97957] = { "⟦Camping=Campeggio⟧ 101: Erbalismo", "Parla con Faruza a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e una ⟦Incense Candle=Candela d'Incenso⟧ può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare una ⟦Incense Candle=Candela d'Incenso⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0xb117ea06, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97958] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con Shelene Rhobart sulla strada da Brill a ⟦Undercity=Sepulcra⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0x90536b6c, 0x86e620e9, nil, nil, "...mm" },
  [97959] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con Brom Killian a ⟦Undercity=Sepulcra⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x352725d8, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97960] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con Rand Rhobart sulla strada da Brill a ⟦Undercity=Sepulcra⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, "Ecco fatto, ora puoi creare il tuo Sedia da Campo. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x14236b38, 0xab414e66, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97961] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con Bowen Brisboise sulla strada da ⟦Deathknell=Albamorta⟧ a Brill per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, "Ecco fatto, ora puoi creare il tuo Stendardo d'Adunata. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xde7f398c, 0xe62978ca, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [97963] = { "⟦Camping=Campeggio⟧ 101: Alchimia", "Parla con Nyassa Swiftdraught al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque hai scelto di preparare intrugli e pozioni come alchimista. Di sicuro ti tornerà utile nei tuoi viaggi.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Mana Well=Pozzo di Mana⟧ per il tuo accampamento. Costruiscine uno e tutti i guaritori e i lanciatori di incantesimi accorreranno per gustarne un sorso rinfrescante.", nil, "Ecco fatto: ora puoi fabbricare un ⟦Mana Well=Pozzo di Mana⟧ tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x32f4ba12, 0x13d46d67, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97964] = { "⟦Camping=Campeggio⟧ 101: Forgiatura", "Parla con Aedi Thriceforged al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una ⟦Sharpening Wheel=Mola per Affilare⟧. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", "Posso insegnarti, se hai l'attitudine.", "Ecco fatto, ora puoi creare il tuo Mola per Affilare. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0x16979ea3, 0x2e5ffa5c, 0x469a706e, 0xfee6b233, 0xe5c38af5, "....." },
