  [97969] = { "⟦Camping=Campeggio⟧ 101: Conciatura", "Parla con ⟦Indari Sunseam=Indari Cucisole⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, "Ecco fatto: una tenda da campo tutta tua. Alla gente non piace granché vedere tende montate in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x40d05936, 0x02561574, 0x86e620e9, nil, 0x01530ff6, "...m." },
  [97970] = { "⟦Camping=Campeggio⟧ 101: Estrazione", "Parla con Messana Crestwind al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campo della tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un ⟦Lodestone=Magnetite⟧ per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", "Posso addestrarti se hai l'attitudine.", "Ecco fatto: ora puoi fabbricare un ⟦Lodestone=Magnetite⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xa8fe12f3, 0x797ded19, 0x8ef0fff6, 0xfebb9665, 0x0b8098cd, "....." },
  [97971] = { "⟦Camping=Campeggio⟧ 101: Scuoiatura", "Parla con Mendalass Tattermend al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una ⟦Camp Chair=Sedia da Campo⟧ per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", "Sì, {class}. Posso insegnarti.", "Ecco fatto: ora puoi fabbricare una ⟦Camp Chair=Sedia da Campo⟧ tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0x14236b38, 0xb45769bd, 0x1755b1ba, 0x2ecf2d20, 0x98c24a76, "....." },
  [97972] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con ⟦Taleen Shimmerthread=Taleen Filolucente⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0x496099ef, 0x49663bd1, nil, nil, "...mm" },
  [97973] = { "⟦Camping=Campeggio⟧ 101: Sartoria", "Parla con ⟦Taleen Shimmerthread=Taleen Filolucente⟧ al ⟦Shen'dar Village=Villaggio di Shen'dar⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare uno ⟦Faction Banner=Stendardo della Fazione⟧ per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", "Torna a parlare con me quando avrai acquisito un po' di abilità nella tua professione.", "Ecco fatto, ora puoi creare il tuo Stendardo d'Adunata. La maggior parte della gente non apprezza molto che si allestiscano accampamenti nel centro della città, quindi dovrai addentrarti nella natura selvaggia se vuoi provarlo.\n\nAh, e ricorda, nessun accampamento è completo senza un falò. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nelle arti culinarie per imparare le basi.", 0xde7f398c, 0x496099ef, 0x49663bd1, 0x6c0def5f, 0x8e312c30, "....." },
  [97977] = { "Il richiamo della natura", "Raccogli $N1 Gnarlpine Totem e portali a Tarindrella.", "I mezzorsi ⟦Gnarlpine=Mordipigna⟧ non si sarebbero rivoltati così facilmente contro i loro antichi alleati. Dobbiamo saperne di più sulla loro sorte.\n\nCerca dei totem nelle loro case abbandonate. Se qualcuno è sopravvissuto al caos della loro partenza, le incisioni potrebbero dirci di più su ciò che è successo qui.\n\nTroverai i loro accampamenti lungo il margine occidentale della valle, anche se i grell e i grellkin potrebbero averli sparpagliati più in là.", "Non preoccuparti degli eventuali totem più grandi che potresti trovare. Non saprei che farmene, anche se trovassi un modo per portarli qui!", "Oh, è persino peggio di quanto pensassi.\n\nQueste incisioni ci dicono che i ⟦Gnarlpine=Mordipigna⟧ cominciarono ad avere incubi in cui venivano sterminati da una grande ombra. In breve quella paura si trasformò in rabbia, e l'ombra nei loro vecchi amici elfi. Rendersi conto che la propria mente sta scivolando via...\n\nLa nostra unica speranza è che questo ci aiuti a capire meglio cosa sta succedendo su Teldrassil. Grazie per il tuo aiuto, {name}.", 0x8ddb1b2f, 0x0263ede4, 0x02e09ddc, 0xc1ecd12f, 0x12ba2b7d, "....." },
  [97979] = { "La dea provvede", "Lancia Elune's Light e Shadowmeld.", "Sei nat<o/a> kaldorei, figli<o/a> delle stelle, e hai ereditato un diritto di nascita che non ha eguali in questo mondo. La grazia di Elune può illuminare la nostra forza, guidando i nostri colpi a segno, o aiutarci a nasconderci come la luna può eclissare il sole.\n\nLa nostra Lunga Veglia dopo la difesa del ⟦Mount Hyjal=Monte Hyjal⟧ è finita, e ci siamo uniti a un'⟦Alliance=Alleanza⟧ con altri popoli, che incontrerai a tempo debito. Per ora sei al riparo tra i rami di Teldrassil.\n\nDimostra i doni di Madre Luna e crogiolati nelle sue benedizioni.", "Ci sono poche gioie così grandi come crogiolarsi nella luce di Madre Luna.", "Hai visto ciò che la nostra dea ci dona. Usalo bene, e lei non ti abbandonerà mai.", 0x1c2fae6f, 0x2d344d16, 0x2061ad94, 0x47c42a76, 0xc6da7ff1, "....." },
  [97985] = { "Cuori tonanti", "Uccidi ⟦Stormheart=Cuorditempesta⟧ a ⟦Thousand Needles=Millepicchi⟧ e prendine il cuore.", "Affascinanti, vero? È la prima volta che mi vengono svelati i segreti della creazione degli abomini.\n\nHo studiato questi appunti, e a quanto pare ci serve un cuore. Uno enorme!\n\nHo sentito dire che a ⟦Thousand Needles=Millepicchi⟧ c'è un sauro del tuono di dimensioni impressionanti, chiamato ⟦Stormheart=Cuorditempesta⟧, che pattuglia il bordo del canyon. Con un nome del genere deve avere il cuore perfetto. Devo avere quel cuore!\n\nAh, ti consiglio anche di portare degli amici. ⟦Stormheart=Cuorditempesta⟧ non è noto per la sua docilità.", "Oh, sei tornat<o/a> tutto d'un pezzo! Peccato: altrimenti le tue ossa e quel che restava della tua carne sarebbero state un ottimo materiale per i miei esperimenti.", "Eccellente! Riesco a stento a contenere l'entusiasmo. Oh, e il cuore ha ancora degli impulsi elettrici? Notevole. Allora non dovrò riportarlo in vita con una scossa!\n\nQuesto cuore sarà un'aggiunta meravigliosa per l'abominio, e sembra proprio della misura indicata, se questi appunti sono giusti.\n\nAh, adoro quando un piano funziona.", 0xf631fcf2, 0xc353cffe, 0x745e4a8c, 0xf005c39c, 0xcbdbeb21, "....." },
  [97986] = { "Arbitro d'Argento", "Parla con il medico dell'altro accampamento da campo dell'⟦Argent Dawn=Alba d'Argento⟧ a nordovest del ⟦Blackwood Lake=Lago di Selvanera⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Una delle nostre esploratrici d'argento, Hailen, è assegnata alle zone periferiche e agli altopiani. Tende a tornare al campo ogni due settimane.\n\nA giudicare dalla tua descrizione, è possibile che siano stati i suoi resti ciò che hai trovato. Ma non abbiamo visto altri Celesti come quelli che hai visto sulla riva del fiume.\n\nAbbiamo un altro campo avanzato a nord-ovest del ⟦Blackwood Lake=Lago di Selvanera⟧. Anche il medico lì potrebbe sapere qualcosa. Molto altro da vedere in prima linea.", nil, nil, 0xbdc47275, 0x5d73b8eb, 0x89fac15d, nil, nil, "...mm" },
  [97987] = { "L'alto ordine di Roccavento", "Parla con Saera Wirraway a ⟦Stormwind=Roccavento⟧, nel Parco.", "Più o meno quando queste scogliere sono crollate, ho sentito sparare delle baliste elfiche. I dardi sono caduti pericolosamente vicino a casa mia lungo la strada per Quel'Thalas.\n\nHo preso la fuga, lasciandomi alle spalle la valanga di alberi e detriti. Ho sentito delle grida in quello che poteva essere solo shen'dorei! Era aspro persino per le mie orecchie. Ho colto solo poche parole: \"traditore\", \"sangue\", \"nemico\".\n\nIl mio suggerimento: porta questa informazione a Saera Wirraway, una Celeste di alto rango nel Parco di Roccavento. Anche se non siamo della stessa stirpe, una volta condividevamo la sete di risposte.", nil, nil, 0x033fc312, 0xd5b49581, 0xe6f6841d, nil, nil, "...mm" },
  [97988] = { "I Plasmatori di Venti di Orgrimmar", "Parla con Corswyn Aseril nella Valle della Saggezza di Orgrimmar.", "Più o meno quando queste scogliere sono crollate, ho sentito sparare delle baliste elfiche. I dardi sono caduti pericolosamente vicino a casa mia lungo la strada per Quel'Thalas.\n\nHo preso la fuga, lasciandomi alle spalle la valanga di alberi e detriti. Ho sentito delle grida in quello che poteva essere solo shen'dorei! Era aspro persino per le mie orecchie. Ho colto solo poche parole: \"traditore\", \"sangue\", \"nemico\".\n\nPorta questa informazione a Corswyn Aseril, un Celeste dei Plasmatori di Venti nella Valle della Saggezza di Orgrimmar. Anche se non siamo della stessa stirpe, i nostri cuori un tempo cercavano la stessa verità.", nil, nil, 0x230fde86, 0xef93f8c9, 0x4f74ca93, nil, nil, "...mm" },
})
